import { Book } from "@/lib/types";

export const joshua: Book = {
  id: "joshua",
  name: "Josua",
  shortName: "Jos",
  testament: "old",
  introduction: `Die Einnahme des verheißenen Landes\n**Das Buch Josua** ist das Kriegs- und Siegesbuch des Alten Testaments. Sein Generalthema ist die Eroberung des verheißenen Landes, die Israel allein der Treue Gottes zu verdanken hat. Kapitel 1-12 umspannen die ersten sieben Jahre nach Moses Tod. Die beiden letzten Kapitel beschreiben Ereignisse, die etwa 24 Jahre später stattfanden. Dazwischen ist die Verteilung des Landes dokumentiert. Josua, der in der ägyptischen Sklaverei geboren wurde und im Alter von 110 Jahren um 1375 v.Chr. als Nachfolger Moses in Kanaan starb, ist die Hauptperson. Einige Teile des Buches (Josua 24,26) stammen von ihm selbst, während das ganze Werk nur wenige Jahrzehnte nach seinem Tod zusammengestellt wurde, vielleicht schon von Pinhas.\n****Wie die Israeliten das von Gott versprochene Land nach und nach eroberten.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Nachdem nun Mose, der Diener* Jahwes, gestorben war, sagte Gott zu Josua Ben-Nun, dem Helfer von Mose:", heading: "1-5: Der Einzug ins Land Kanaan\nJosuas Berufung", footnotes: ["Diener. Wörtlich: Sklave (hebr. äbäd). Das ist ein Mensch, dessen Leben und Arbeit völlig von einem ihm übergeordneten Willen abhängt. In der allgemeinen Wertschätzung wurde er mit Häusern und Vieh gleichgesetzt (1. Mose 24,35). Wer sich selbst als Sklave bezeichnet, anerkennt über sich eine fremde Macht. Auch der höchste Beamte ist dem König gegenüber Sklave. So kann der Titel Sklave auch zum Ehrennamen werden, den Männer wie Mose, David oder die Propheten tragen; sie heißen Sklaven Gottes."] },
      { number: 2, text: "\"Mein Diener Mose ist gestorben. Mach dich jetzt mit dem ganzen Volk bereit, den Jordan zu überqueren und in das Land zu ziehen, das ich den Israeliten geben will." },
      { number: 3, text: "Jedes Stück Land, das ihr betretet, wird euch gehören – wie ich es Mose versprochen habe –" },
      { number: 4, text: "und zwar von der Wüste im Süden bis zum Libanongebirge* im Norden. Euer Land wird nach Osten zu das ganze Gebiet der Hetiter* bis zum Euphrat umfassen und im Westen bis ans Mittelmeer reichen.", footnotes: ["Libanongebirge. Das \"weiße Gebirge\". 170 km lange und 25 km breite Gebirgskette am Mittelmeer nördlich von Israel, deren höchste Gipfel (über 3000 Meter) fast ganzjährig mit Schnee bedeckt sind. Berühmt sind die bis zu 40 Meter hohen Zedern.", "Die Hetiter waren eine kleinasiatische Völkergruppe, die weder in Sprache noch Herkunft eine erkennbare Einheit bildeten. Zu dieser Zeit bestanden in Nordsyrien verschiedene hetitische Staaten."] },
      { number: 5, text: "Dein Leben lang wird sich kein Feind gegen dich behaupten können. So, wie ich Mose beistand, werde ich auch dir beistehen. Ich werde dich nie im Stich lassen, dich niemals vergessen." },
      { number: 6, text: "Sei stark und sei mutig! Du wirst diesem Volk das Land, das ich ihren Vorfahren unter Eid versprochen habe, als bleibenden Besitz austeilen." },
      { number: 7, text: "Halte dich mutig und fest an das Gesetz, das mein Diener Mose dir übergeben hat! Weiche weder rechts noch links davon ab, damit dir alles gelingt, was du unternimmst." },
      { number: 8, text: "Du sollst die Weisungen dieses Gesetzbuches immer vor dir hersagen und Tag und Nacht darüber nachdenken, damit dein Tun ganz von dem bestimmt ist, was darin steht. Dann wirst du Erfolg haben, und was du anpackst, wird dir gelingen." },
      { number: 9, text: "Ich habe es dir gesagt! Sei stark und sei mutig! Lass dir keine Angst einjagen, lass dich nicht einschüchtern, denn Jahwe, dein Gott, steht dir bei, wo du auch bist.\"" },
      { number: 10, text: "Da befahl Josua den Hauptleuten des Volkes" },
      { number: 11, text: "durchs Lager zu gehen und überall bekannt zu machen: \"Versorgt euch mit Verpflegung, denn in drei Tagen werden wir den Jordan überqueren und das Land in Besitz nehmen, das Jahwe, unser Gott, uns zum Eigentum gibt.\"" },
      { number: 12, text: "Zu den Stämmen Ruben, Gad und dem halben Stamm Manasse sagte Josua:" },
      { number: 13, text: "\"Denkt daran, was euch Mose, der Diener Jahwes, gesagt hat: 'Jahwe, euer Gott, gibt euch hier in diesem Land eure Heimat.'" },
      { number: 14, text: "Eure Frauen, eure Kinder und euer Vieh können auf dieser Seite des Jordan bleiben. Doch ihr sollt mit allen kampffähigen Männern bewaffnet vor euren Bruderstämmen hinüberziehen und ihnen helfen," },
      { number: 15, text: "das Land einzunehmen, das Jahwe, ihr Gott, ihnen gibt. Wenn sie dann ihre Heimat gefunden haben, könnt ihr zurückkommen und euch hier, östlich vom Jordan, in dem Land ansiedeln, das Mose, der Diener Jahwes, euch zugeteilt hat.\"" },
      { number: 16, text: "Sie antworteten Josua: \"Wir wollen alles tun, was du uns befohlen hast, und überall hingehen, wohin du uns schickst." },
      { number: 17, text: "Wir werden dir genauso gehorchen, wie wir Mose gehorcht haben. Möge nur Jahwe, dein Gott, so mit dir sein, wie er mit Mose war." },
      { number: 18, text: "Jeder, der sich deinem Befehl widersetzt und deinen Weisungen nicht folgt, soll mit dem Tod bestraft werden. Sei nur stark und sei mutig!\"" },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Von Schittim* aus hatte Josua heimlich zwei Männer als Kundschafter losgeschickt und sie beauftragt, das Land und besonders Jericho* zu erkunden. Die Kundschafter kamen in die Stadt und kehrten im Haus einer Hure namens Rahab ein, um dort zu übernachten.", heading: "Kundschafter in Jericho", footnotes: ["Der Ort (Abel-)Schittim (= viell. \"Akazienbach\") lag 12 km östlich vom Jordan in der Steppe Moabs, am Rand des Jordan-Grabens.", "Jericho. Die alte Kanaanitersiedlung war die Schlüsselfestung des Jordangrabens, die alle Wege ins Gebirge kontrollierte. Es war eine fruchtbare Oase mit viel Wasser. Infolge ihrer geschützten Lage, etwa 250 Meter unter dem Meeresspiegel, besaß die Stadt ein fast tropisches Klima."] },
      { number: 2, text: "Kurz darauf wurde dem König von Jericho gemeldet: \"Kundschafter von den Israeliten sind heute Nacht in die Stadt gekommen.\"" },
      { number: 3, text: "Da schickte der König einige Wachen zu Rahab und befahl: \"Gib die Männer heraus, die bei dir eingekehrt sind. Sie sind nur gekommen, um das Land auszukundschaften.\"" },
      { number: 4, text: "Die Frau hatte die beiden Männer jedoch versteckt und sagte: \"Ja, die Männer sind bei mir gewesen, aber ich wusste nicht, woher sie waren." },
      { number: 5, text: "Kurz vor dem Schließen des Stadttors, bei Einbruch der Dunkelheit, sind sie wieder gegangen. Ich weiß aber nicht, wohin. Wenn ihr sie gleich verfolgt, werdet ihr sie bestimmt einholen.\"" },
      { number: 6, text: "– Rahab hatte die beiden aber auf das flache Dach ihres Hauses gebracht und unter aufgeschichteten Flachsstängeln versteckt. –" },
      { number: 7, text: "Da nahmen die Wachen die Verfolgung auf und suchten den ganzen Weg bis zu den Jordanfurten ab. Sobald sie aus der Stadt waren, wurde das Tor wieder geschlossen." },
      { number: 8, text: "Noch bevor die beiden Israeliten sich schlafen gelegt hatten, kam Rahab zu ihnen aufs Dach" },
      { number: 9, text: "und sagte: \"Ich weiß, dass Jahwe euch das Land geben wird. Uns hat ein derartiges Entsetzen vor euch überfallen, dass alle Bewohner des Landes wie gelähmt sind." },
      { number: 10, text: "Denn wir haben gehört, dass Jahwe das Wasser des Schilfmeeres vor euch ausgetrocknet hat, als ihr aus Ägypten zogt, und wir wissen auch, was ihr mit den beiden Königen der Amoriter* auf der anderen Jordanseite gemacht habt, mit Sihon und Og. Ihr habt den Bann* an ihnen vollstreckt und sie vernichtet.", footnotes: ["Amoriter. Bewohner des Landes Kanaan. Der Begriff kann sowohl für einen einzelnen Stamm als auch für alle Bewohner Kanaans stehen. Es waren semitische Einwanderer aus der Arabischen Wüste, die um 2000 v.Chr. ins Kulturland eindrangen.", "Bann. Das bedeutete die vollständige Vernichtung von Menschen, Tieren und Gütern. Im Fall von Sihon und Og betraf es nur die Menschen."] },
      { number: 11, text: "Als wir das hörten, haben wir allen Mut verloren. Keiner von uns wagt es noch, gegen euch zu kämpfen. Ja, euer Gott, Jahwe, er ist Gott im Himmel oben und auf der Erde unten." },
      { number: 12, text: "Nun bitte ich euch, schwört mir bei Jahwe, dass ihr meine Familie genauso verschont, wie ich euch verschont habe, und gebt mir ein sicheres Zeichen," },
      { number: 13, text: "dass ihr meine Angehörigen, meinen Vater, meine Mutter, meine Brüder und Schwestern und alle, die zu ihnen gehören, am Leben lasst, dass ihr uns rettet vom Tod.\"" },
      { number: 14, text: "Da sagten die Kundschafter zu ihr: \"Unser Leben steht für euer Leben! Wenn ihr unsere Sache nicht verratet, werden wir dich und deine Angehörigen verschonen, wenn Jahwe uns dieses Land gibt.\"" },
      { number: 15, text: "Bevor Rahab die beiden Männer nun durchs Fenster an einem Seil die Mauer hinunterließ, – ihr Haus war nämlich an die Stadtmauer gebaut, sie wohnte praktisch direkt in der Mauer –" },
      { number: 16, text: "sagte sie zu ihnen: \"Geht zuerst ins Gebirge und versteckt euch dort drei Tage, damit ihr nicht den Verfolgern in die Arme lauft. Wenn sie dann zurück gekommen sind, könnt ihr gehen, wohin ihr wollt.\"" },
      { number: 17, text: "Und die Kundschafter sagten: \"Damit wir unseren Eid halten können, musst du Folgendes tun:" },
      { number: 18, text: "Binde diese rote Schnur an das Fenster, durch das du uns herunterlassen wirst, und hole deinen Vater, deine Mutter, deine Brüder und alle deine Verwandten zu dir ins Haus." },
      { number: 19, text: "Niemand darf das Haus verlassen, sonst ist er selbst für seinen Tod verantwortlich und wir sind von unserem Eid frei. Doch für jeden, der im Haus bleibt, tragen wir die Verantwortung, dass niemand ihn antastet." },
      { number: 20, text: "Natürlich darfst du auch unsere Sache nicht verraten, sonst sind wir nicht mehr an den Eid gebunden, den wir dir geschworen haben.\"" },
      { number: 21, text: "\"Einverstanden\", sagte sie, \"so soll es sein\", und ließ sie gehen. Dann band sie die rote Schnur ans Fenster." },
      { number: 22, text: "Die Männer versteckten sich drei Tage lang in den Bergen, bis die Verfolger in die Stadt zurückgekehrt waren. Sie hatten alle Wege abgesucht und sie nicht gefunden." },
      { number: 23, text: "Jetzt machten sich die Kundschafter auf den Rückweg. Sie stiegen vom Gebirge herab und überquerten den Jordan. Als sie wieder bei Josua Ben-Nun waren, berichteten sie ihm alles, was sie erlebt hatten." },
      { number: 24, text: "Sie versicherten ihm: \"Jahwe hat das ganze Land in unsere Hand gegeben. Alle Einwohner zittern vor uns.\"" },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Früh am nächsten Morgen brach Josua von Schittim auf und zog mit dem ganzen Volk Israel bis an den Jordan. Sie überquerten den Fluss aber noch nicht, sondern übernachteten dort.", heading: "Der Weg durch den Jordan" },
      { number: 2, text: "Am dritten Tag schickte Josua die Hauptleute mit dem Befehl durchs Lager:" },
      { number: 3, text: "\"Sobald ihr seht, dass die Lade Jahwes, die Lade eures Bundes mit Gott, von Priestern aus dem Stamm Levi getragen wird, dann brecht auf und zieht hinter ihr her." },
      { number: 4, text: "Sie wird euch einen Weg zeigen, den ihr vorher noch nie gegangen seid. Ihr dürft der Lade aber nicht zu nahe kommen, sondern müsst einen Abstand von etwa tausend Metern* zu ihr halten.\"", footnotes: ["etwa 1000 Metern. Wörtlich: 2000 Ellen."] },
      { number: 5, text: "Weiter ließ Josua dem Volk sagen: \"Heiligt* euch, denn morgen wird Jahwe in eurer Mitte Wunder tun.\"", footnotes: ["Heiligt euch. Das bedeutete für die Israeliten, dass sie ihre Kleider und sich selbst waschen mussten und keinen Geschlechtsverkehr haben durften (siehe 2. Mose 19,10.14-15; 3. Mose 16,4.24)."] },
      { number: 6, text: "Am nächsten Tag befahl Josua den Priestern: \"Nehmt die Bundeslade auf und zieht dem Volk voran!\" Da hoben sie die Bundeslade auf und zogen vor dem Volk her." },
      { number: 7, text: "Da sagte Jahwe zu Josua: \"Heute will ich anfangen, dich vor dem ganzen Volk Israel groß zu machen. Sie sollen merken, dass ich dir beistehe, wie ich Mose zur Seite stand." },
      { number: 8, text: "Befiehl den Priestern, die die Bundeslade tragen: 'Wenn ihr an den Rand des Wassers kommt, bleibt ihr im Jordan stehen!'\"" },
      { number: 9, text: "Dann rief Josua das Volk Israel zu sich: \"Kommt her und hört, was Jahwe, euer Gott, euch sagt!" },
      { number: 10, text: "Ihr werdet gleich sehen, dass der lebendige Gott unter euch ist und dass er die Völker des Landes, die Kanaaniter*, Hetiter, Hiwiter*, Perisiter*, Girgaschiter*, Amoriter und Jebusiter* vor euch vertreiben wird.", footnotes: ["Kanaaniter. Bewohner des Landes Kanaan auf dem Gebiet des heutigen Israel. Sie besaßen eine gemeinsame Sprache, Religion und Kultur, waren politisch aber in viele Kleinkönigtümer und Stadtstaaten zersplittert.", "Hiwiter. Bewohner Kanaans. Die Einwohner der Städte Gibeon, Kefira, Beerot und Kirjat-Jearim gehörten zu ihnen. Ihr Hauptsiedlungsgebiet scheint am Libanon zwischen Hermon und Hamat gelegen zu haben.", "Perisiter. Nicht näher bekanntes Volk in Kanaan; möglicherweise die bäuerliche Bevölkerung.", "Girgaschiter. Das Volk kommt nur in der Aufzählung der kanaanitischen Stämme vor, ihr Wohnsitz ist nicht bekannt.", "Jebusiter. Bewohner Kanaans, die auf dem Gebirge und in Jebus (Jerusalem) siedelten."] },
      { number: 11, text: "Passt auf! Die Bundeslade Jahwes, des Herrschers über die ganze Erde, wird jetzt durch den Jordan ziehen." },
      { number: 12, text: "Wählt zwölf Männer aus, von jedem Stamm einen!" },
      { number: 13, text: "Wenn dann die Priester, die diese Lade Jahwes, des Herrn der ganzen Erde, tragen, ihre Füße ins Jordanwasser setzen, wird kein Wasser mehr nachfließen. Der Fluss wird sich weiter oben anstauen wie vor einem Damm.\"" },
      { number: 14, text: "Nun brach das Volk auf, um durch den Jordan zu ziehen. An der Spitze des Zuges trugen die Priester die Bundeslade." },
      { number: 15, text: "Als sie ihre Füße ins Wasser setzten – der Jordan führt während der ganzen Erntezeit Hochwasser –," },
      { number: 16, text: "da staute sich der Fluss sehr weit oben bei der Stadt Adam*, in der Nähe von Zaretan. Dort richtete sich ein Damm auf. Und das Wasser, das zum Meer der Araba*, dem Toten Meer, hinabfloss, verlief sich völlig. So konnte das Volk gegenüber von Jericho trockenen Fußes durch den Jordan gehen.", footnotes: ["Adam. Die Stadt liegt etwa 30 km nördlich von der Übergangsstelle in der Jordanebene, 2 km südlich der Mündung des Jabbok.", "Als Araba wird der Jordangraben bezeichnet, der sich von Norden nach Süden durch ganz Israel zieht, sogar noch über das Tote Meer hinaus bis nach Elat. Er ist zwischen 12,5 und 22,5 km breit und befindet sich fast überall unter Meersspiegel, im Toten Meer 394 Meter unter NN."] },
      { number: 17, text: "Die Priester blieben mit der Bundeslade Jahwes mitten im Flussbett stehen, bis die ganze Nation den Jordan überschritten hatte." },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Als das ganze Volk den Jordan durchzogen hatte, sagte Jahwe zu Josua:", heading: "Das Denkmal" },
      { number: 2, text: "\"Befiehl den zwölf Männern, die aus jedem Stamm ausgewählt worden sind," },
      { number: 3, text: "zwölf Steine mitten aus dem Jordan zu holen und zwar von der Stelle, wo die Priester stehen. Sie sollen die Steine mit euch hinüberschaffen und dort hinlegen, wo ihr das Nachtlager aufschlagt.\"" },
      { number: 4, text: "Da rief Josua die zwölf Männer" },
      { number: 5, text: "und sagte zu ihnen: \"Geht jetzt bis vor die Lade Jahwes, eures Gottes, in den Jordan, und jeder von euch soll einen großen Stein auf die Schulter heben – so viel Steine, wie Israel Stämme hat." },
      { number: 6, text: "Die Steine sollen ein Denkmal für euch sein. Wenn später eure Kinder fragen, was es mit diesen Steinen auf sich hat," },
      { number: 7, text: "dann sollt ihr ihnen erzählen, wie das Wasser des Jordan abriss, als die Bundeslade Jahwes hindurchzog. Die Steine sollen euch in aller Zukunft daran erinnern.\"" },
      { number: 8, text: "Die Männer gehorchten Josua und hoben zwölf Steine aus dem Jordan, für jeden Stamm einen, wie Jahwe es befohlen hatte. Sie trugen sie bis zum Lagerplatz und legten sie dort nieder." },
      { number: 9, text: "Josua aber schichtete mitten im Jordan an der Stelle, wo die Priester mit der Bundeslade standen, ebenfalls zwölf Steine auf. Dort liegen sie heute* noch.", footnotes: ["Heute. Zum Zeitpunkt der Abfassung des Buches Josua."] },
      { number: 10, text: "Während der ganzen Zeit blieben die Priester mit der Bundeslade mitten im Jordan stehen, bis alles ausgeführt war, was Jahwe dem Volk durch Josua befohlen hatte, genauso, wie es schon Mose Josua aufgetragen hatte. Das Volk beeilte sich, durch das trockene Flussbett zu kommen." },
      { number: 11, text: "Sobald alle den Fluss überquert hatten, kamen auch die Priester mit der Bundeslade Jahwes ans andere Ufer. Das ganze Volk sah zu." },
      { number: 12, text: "Die Männer von den Stämmen Ruben, Gad und vom halben Stamm Manasse waren bewaffnet vor den Israeliten hergezogen, wie Mose es ihnen befohlen hatte." },
      { number: 13, text: "Etwa 40.000 Bewaffnete zogen so vor Jahwe zum Kampf in die Ebene von Jericho." },
      { number: 14, text: "An diesem Tag machte Jahwe Josua vor dem ganzen Volk groß. Die Israeliten hatten den gleichen Respekt vor ihm, wie sie ihn vor Mose gehabt hatten. Und so blieb es sein Leben lang." },
      { number: 15, text: "Dann sagte Jahwe zu Josua:" },
      { number: 16, text: "\"Befiehl den Priestern, mit der Bundeslade aus dem Jordan herauszukommen.\"" },
      { number: 17, text: "Josua gab den Befehl," },
      { number: 18, text: "und kaum hatten die Fußsohlen der Priester das trockene Ufer betreten, da kehrte das Wasser des Jordan in sein Bett zurück, und der Fluss trat wieder über seine Ufer." },
      { number: 19, text: "Es war am 10. April* als das Volk durch den Jordan zog und sein Lager bei Gilgal* an der Ostgrenze des Stadtgebietes von Jericho aufschlug.", footnotes: ["April Wörtlich: des 1. Monats. 1405 v.Chr. Zum Datum siehe unter Schaltmonat im Vorwort des Übersetzers.", "Gilgal. Der Ort wird gewöhnlich mit den Ruinen von Kirbet el-Mafjer identifiziert, 3 km nordöstlich von Jericho. \"Gilgal\" klingt an das hebr. Wort für Kreis an (Steinkreis wie vielleicht Josua 4,20) oder an \"rollen, wälzen\" wie Josua 5,9."] },
      { number: 20, text: "Dort richtete Josua die zwölf Steine auf*, die sie aus dem Jordan geholt hatten,", footnotes: ["richtete ... auf. Entweder als Kreis (siehe Gilgal) oder als Steinhaufen."] },
      { number: 21, text: "und sagte zu den Israeliten: \"Wenn eure Kinder später ihre Väter fragen, was diese Steine bedeuten," },
      { number: 22, text: "dann sollt ihr es ihnen so erklären: 'Diesen Jordan hat Israel trockenen Fußes durchquert.'" },
      { number: 23, text: "Denn Jahwe, euer Gott, hat das Wasser des Jordan vor euch austrocknen lassen, bis ihr hindurchgezogen wart, genauso, wie er auch das Schilfmeer vor uns austrocknete, damit wir durchziehen konnten." },
      { number: 24, text: "Alle Völker der Erde sollen daran erkennen, wie groß die Macht Jahwes ist, damit auch ihr eurem Gott Jahwe immer mit Ehrfurcht begegnet.\"" },
    ] },
    { number: 5, verses: [
      { number: 1, text: "Alle Amoriterkönige westlich des Jordan und alle Kanaaniterkönige an der Küste des Mittelmeers hörten, dass Jahwe das Wasser des Jordan vor den Israeliten hatte vertrocknen lassen, bis sie durchgezogen waren. Da wurden sie von Angst gepackt und verloren allen Mut vor Israel." },
      { number: 2, text: "In dieser Zeit sagte Jahwe zu Josua: \"Mach dir Steinmesser und wiederhole die Beschneidung* an allen männlichen Israeliten!\"", heading: "Beschneidung in Gilgal", footnotes: ["Beschneidung. Siehe 1. Mose 17,9-14!"] },
      { number: 3, text: "Da fertigte sich Josua Steinmesser an und beschnitt alle männlichen Israeliten an einem Platz, der seitdem \"Hügel der Vorhäute\" heißt." },
      { number: 4, text: "Das geschah aus folgendem Grund: Alle männlichen Israeliten, die Ägypten im wehrfähigen Alter verließen, waren in der Wüste gestorben." },
      { number: 5, text: "Sie waren beschnitten gewesen. Während der Wüstenwanderung aber waren die Neugeborenen nicht beschnitten worden." },
      { number: 6, text: "Das Volk Israel musste ja vierzig Jahre in der Wüste umherziehen, bis alle Männer, die Ägypten im wehrfähigen Alter verlassen hatten, umgekommen waren. Sie waren Jahwe ungehorsam gewesen, und er hatte ihnen geschworen: \"Sie sollen das Land nicht sehen, das ich ihren Vätern versprochen habe, das Land, das von Milch und Honig überfließt!\"" },
      { number: 7, text: "Jahwe hatte ihre Söhne an ihre Stelle treten lassen. Diese beschnitt Josua jetzt, denn sie waren unterwegs nicht beschnitten worden." },
      { number: 8, text: "Nachdem nun alle beschnitten waren, blieben sie im Lager, bis ihre Wunden wieder heilten." },
      { number: 9, text: "Jahwe sagte zu Josua: \"Heute habe ich die ägyptische Schmach von euch abgewälzt.\" Deshalb wird der Ort bis heute Gilgal, Abwälzung, genannt." },
      { number: 10, text: "Während die Israeliten noch in der Ebene von Jericho bei Gilgal lagerten, feierten sie das Passafest.* Das war am Abend des 14. April*.", footnotes: ["April Wörtlich: des Monats.", "Passa. Siehe 2. Mose 12-13."] },
      { number: 11, text: "Und am Tag nach dem Passa aßen sie vom Ertrag des Landes: ungesäuertes Fladenbrot und geröstete Getreidekörner." },
      { number: 12, text: "Von diesem Tag an blieb das Manna aus. Die Israeliten fanden keins mehr und aßen schon in diesem Jahr das, was in Kanaan gewachsen war." },
      { number: 13, text: "In der Nähe von Jericho sah Josua sich plötzlich einem Mann gegenüberstehen, der ein gezogenes Schwert in der Hand hatte. Josua ging auf ihn zu und fragte: \"Gehörst du zu uns oder zu unseren Feinden?\"", heading: "Die Zerstörung Jerichos" },
      { number: 14, text: "\"Zu keinem von beiden\", sagte der Fremde, \"ich bin der Befehlshaber des Heeres Jahwes und bin gerade angekommen.\" Da warf sich Josua voller Ehrfurcht vor ihm auf den Boden und sagte: \"Ich bin dein Diener. Was befiehlst du mir, Herr?\"" },
      { number: 15, text: "\"Zieh deine Sandalen aus\", erwiderte der Befehlshaber des Heeres Gottes, \"du stehst auf heiligem Boden!\" Josua gehorchte." },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Wegen der Israeliten hatte Jericho alle Tore geschlossen und fest verriegelt. Niemand konnte mehr heraus und hinein.", heading: "6-12: Die Eroberung des Landes" },
      { number: 2, text: "\"Pass auf!\", sagte Jahwe zu Josua: \"Ich gebe Jericho mitsamt seinem König und allen seinen Kämpfern in deine Gewalt." },
      { number: 3, text: "Sechs Tage lang sollt ihr jeden Tag einmal mit allen bewaffneten Männern um die Stadt herumziehen." },
      { number: 4, text: "Sieben Priester sollen mit je einem Schofar-Horn* vor der Bundeslade hergehen. Am siebten Tag sollt ihr sieben Mal um die Stadt herumziehen, wobei die Priester den Schofar blasen sollen.", footnotes: ["Der Schofar war aus den gewundenen Hörnern des männlichen Fettschwanzschafes hergestellt und brachte einen dumpfen, durchdringenden Ton hervor."] },
      { number: 5, text: "Wenn dann der langgezogene Ton des Widderhorns dröhnt, soll das ganze Volk ein lautes Kriegsgeschrei anstimmen. In diesem Moment wird die Mauer in sich zusammenstürzen, und jeder soll von der Stelle aus, wo er sich gerade befindet, in die Stadt eindringen.\"" },
      { number: 6, text: "Josua rief die Priester zu sich und befahl ihnen: \"Nehmt die Bundeslade Jahwes auf eure Schultern! Sieben von euch sollen mit je einem Schofar-Horn vor ihr herziehen.\"" },
      { number: 7, text: "Zum Volk sagte er: \"Zieht um die Stadt herum und lasst die Vorhut der Bewaffneten vor der Lade Jahwes hergehen.\"" },
      { number: 8, text: "Als Josua dem Volk diesen Befehl erteilt hatte, setzten sich die sieben Priester in Bewegung. Sie trugen je ein Schofar-Horn vor Jahwe her und bliesen es immerfort. Die Bundeslade Jahwes folgte ihnen." },
      { number: 9, text: "Vor den Priestern zog die Vorhut der Bewaffneten. Als Nachhut folgte das übrige Heer. Sie gingen und die Priester stießen unentwegt in den Schofar." },
      { number: 10, text: "Dem Volk hatte Josua befohlen, keinen Lärm zu machen und sich ganz still zu verhalten. Erst auf seinen Befehl hin sollten sie das Kriegsgeschrei anstimmen." },
      { number: 11, text: "So zogen sie mit der Lade Jahwes einmal um die Stadt und kehrten anschließend in ihr Lager zurück, wo sie übernachteten." },
      { number: 12, text: "Früh am nächsten Morgen ließ Josua sie wieder aufbrechen: Die Priester trugen die Lade Jahwes," },
      { number: 13, text: "sieben von ihnen zogen vor ihr her und bliesen dabei ständig das Schofar-Horn. Vor ihnen her zog die Vorhut der Bewaffneten und nach der Lade Jahwes folgte als Nachhut das übrige Heer. Es war ein Gehen unter ständigem Schofar-Getön." },
      { number: 14, text: "Wie am Vortag zogen sie einmal um die Stadt und kehrten dann in ihr Lager zurück. So machten sie es sechs Tage lang." },
      { number: 15, text: "Am siebten Tag machten sie sich beim Morgengrauen in derselben Ordnung auf und zogen sieben Mal um die Stadt. Nur an diesem Tag umrundeten sie die Stadt sieben Mal." },
      { number: 16, text: "Als die Priester das siebte Mal in die Hörner stoßen wollten, befahl Josua dem Volk: \"Jetzt müsst ihr mit dem Kriegsgeschrei beginnen, denn Jahwe hat Jericho in unsere Gewalt gegeben!" },
      { number: 17, text: "Aber die ganze Stadt mit allem, was darin ist, soll dem Bann Jahwes verfallen sein. Nur Rahab, die Hure, die unsere Kundschafter versteckt hat, soll mit allen Menschen in ihrem Haus verschont werden." },
      { number: 18, text: "Hütet euch davor, irgendetwas von dem Gebannten zu begehren und an euch zu nehmen, sonst bringt ihr das Lager Israels unter den Bann und stürzt es ins Verderben!" },
      { number: 19, text: "Alles Gold und Silber und alle Gegenstände aus Bronze und Eisen sind für Jahwe bestimmt und kommen in den Schatz seines Heiligtums!\"" },
      { number: 20, text: "Da stießen sie in die Hörner, und das Volk begann mit einem gewaltigen Kriegsgeschrei. In diesem Moment brach die ganze Mauer in sich zusammen*. Da stürmten die Israeliten von allen Seiten in die Stadt und eroberten sie.", footnotes: ["brach ... zusammen. Neuere Untersuchungen der Ausgrabungen Jerichos belegen, dass die Stadt Anfang des 15. Jahrhunderts v.Chr. zerstört wurde."] },
      { number: 21, text: "Mit dem scharfen Schwert in der Hand vollstreckten sie den Bann an allem, was in der Stadt lebte: an Männern und Frauen, Alten und Jungen, Rindern, Schafen und Eseln." },
      { number: 22, text: "Den beiden Kundschaftern hatte Josua gesagt: \"Geht in das Haus der Hure und holt sie samt ihren Angehörigen heraus, wie ihr es geschworen habt.\"" },
      { number: 23, text: "Da gingen die jungen Männer hin und brachten Rahab zusammen mit ihrem Vater, ihrer Mutter, ihren Geschwistern und allen Verwandten aus der Stadt und wiesen ihnen einen Platz außerhalb vom Lager Israels an." },
      { number: 24, text: "Dann wurde die ganze Stadt niedergebrannt, nur das Gold und das Silber, die eisernen und die bronzenen Gegenstände brachte man in den Schatz im Heiligtum Jahwes." },
      { number: 25, text: "So verschonte Josua die Hure Rahab und ihre ganze Familie, weil sie die Kundschafter in Jericho versteckt hatte. Und sie lebt ja heute noch in Israel." },
      { number: 26, text: "Damals ließ Josua das Volk diesen Eid schwören: \"Verflucht sei der Mann, der sich erhebt und diese Stadt Jericho wieder baut! Wenn er ihre Fundamente legt, kostet es ihn seinen ältesten Sohn, und wenn er ihre Tore einsetzt, seinen jüngsten.\"" },
      { number: 27, text: "Jahwe stand Josua zur Seite, und im ganzen Land sprach man von ihm." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Aber die Israeliten veruntreuten etwas von dem Gebannten. Achan Ben-Karmi, der von Sabdi und Serach abstammte und aus dem Stamm Juda war, vergriff sich an dem, was Gott gehörte. Da flammte Jahwes Zorn gegen die Israeliten auf.", heading: "Achans Vergehen" },
      { number: 2, text: "Josua schickte einige Männer von Jericho nach Ai*, das bei Bet-Awen* liegt, östlich von Bet-El*, und befahl ihnen, die Umgebung der Stadt Ai zu erkunden. Die Männer führten den Auftrag aus", footnotes: ["Ai. 1995 wurde in Kirbet el-Maqatir, etwa 1 km westlich von Et-Tell eine Festung ausgegraben, die um 1400 v.Chr. durch Feuer zerstört wurde. Weil auch die Topografie des Gebietes mit den Angaben von Josua 7-8 übereinstimmt, handelt es sich höchstwahrscheinlich um Ai.", "Bet-Awen. Haus des Unheils, kleiner Ort östlich von Bet-El. In späterer Zeit wurde Bet-El wegen seines Götzendienstes so bezeichnet.", "Bet-El. Hebr.: Haus Gottes."] },
      { number: 3, text: "und berichteten Josua: \"Die Stadt ist nicht groß. Du musst nicht das ganze Heer aufbieten, um Ai zu erobern, zwei- bis dreitausend Mann genügen völlig." },
      { number: 4, text: "So zogen etwa 3000 Männer dort hinauf* und griffen die Stadt an. Doch sie wurden in die Flucht geschlagen.", footnotes: ["hinauf. Jericho liegt im Jordangraben etwa 250 Meter unter dem Meeresspiegel. Ai liegt 913 Meter über NN. Die Israeliten mussten eine Entfernung von etwa 20 km und einen Höhenunterschied von mehr als 1100 Meter bewältigen."] },
      { number: 5, text: "Die Männer von Ai verfolgten sie vom Stadttor an bis zu den Steinbrüchen und dem Aufstieg. Sie erschlugen etwa 36 Mann. Da verlor das Volk allen Mut." },
      { number: 6, text: "Josua und die Ältesten zerrissen ihre Gewänder*, streuten sich Erde auf den Kopf und warfen sich vor der Lade Jahwes auf den Boden. So lagen sie bis zum Abend.", footnotes: ["zerrissen ihre Gewänder. Trauerbrauch. Man riss das Gewand vom Halssaum an auf und entblößte die Brust."] },
      { number: 7, text: "Josua betete: \"Ach Herr, Jahwe! Warum hast du uns nur über den Jordan geführt, wenn du uns nun in die Hände der Amoriter fallen lässt, damit sie uns vernichten? Hätten wir uns doch daran genügen lassen, auf der anderen Jordanseite zu bleiben!" },
      { number: 8, text: "Bitte, Herr, was soll ich denn jetzt sagen, nachdem Israel vor seinen Feinden geflohen ist?" },
      { number: 9, text: "Wenn das die Kanaaniter und die anderen Bewohner des Landes hören, werden sie uns umbringen und unseren Namen in diesem Land auslöschen. Was wirst du dann für die Ehre deines großen Namens tun?\"" },
      { number: 10, text: "Da sagte Jahwe zu Josua: \"Steh auf! Warum liegst du hier auf dem Boden?" },
      { number: 11, text: "Israel hat gesündigt! Das Volk hat den Bund gebrochen, den ich mit ihm geschlossen habe. Sie haben etwas von dem Gebannten genommen. Sie haben es gestohlen und heimlich bei sich versteckt." },
      { number: 12, text: "Die Israeliten werden ihren Feinden nicht mehr standhalten können. Sie werden vor ihnen fliehen müssen, denn sie selbst sind zum Bann geworden. Ich werde nicht mehr mit euch sein, wenn ihr nicht alles, was ihr aus dem Gebannten genommen habt, vernichtet." },
      { number: 13, text: "Steh auf und sorge dafür, dass das Volk sich heiligt! Befiehl ihnen: 'Heiligt euch für morgen! Denn so spricht Jahwe, Israels Gott: Gebanntes ist in deinem Besitz, Israel! Du wirst vor deinen Feinden nicht bestehen können, bis du das Gebannte aus deiner Mitte entfernt hast." },
      { number: 14, text: "Morgen früh sollt ihr euch in Stammesverbänden geordnet vor Jahwe hinstellen. Dann soll der Stamm vortreten, den Jahwe treffen wird*, dann die Sippe und dann die Familie.", footnotes: ["den Jahwe treffen wird. Offenbar durch die heiligen Lose, die sich in der Brusttasche des Hohen Priesters befanden."] },
      { number: 15, text: "Derjenige, bei dem man etwas von dem Gebannten findet, soll mit allem, was zu ihm gehört, verbrannt werden! Das muss sein, denn er hat den Bund Jahwes gebrochen und eine Schandtat in Israel begangen.'\"" },
      { number: 16, text: "Früh am nächsten Morgen ließ Josua das Volk nach seinen Stammesverbänden geordnet antreten. Getroffen wurde der Stamm Juda." },
      { number: 17, text: "Als Juda mit seinen Sippen vortrat, wurde die Sippe Serach getroffen. Aus der Sippe Serach traf es die Familie Sabdi." },
      { number: 18, text: "Unter den Männern dieser Familie wurde schließlich Achan Ben-Karmi getroffen. Seine Vorfahren waren Sabdi und Serach aus dem Stamm Juda." },
      { number: 19, text: "Josua sagte zu Achan: \"Mein Sohn, gib Jahwe, dem Gott Israels, die Ehre und leg vor ihm ein Geständnis ab. Sag mir offen, was du getan hast, und verschweige nichts.\"" },
      { number: 20, text: "\"Es ist wahr\", erwiderte Achan, \"ich habe gegen Jahwe, den Gott Israels gesündigt. Und das habe ich getan:" },
      { number: 21, text: "Unter den Beutestücken sah ich einen schönen babylonischen Mantel, mehr als zwei Kilogramm Silberstücke und einen Goldbarren von einem halben Kilogramm Gewicht*. Ich bekam Lust nach diesen Dingen und nahm sie mir. Sie sind alle unter meinem Zelt vergraben, das Silber ganz unten.\"", footnotes: ["Gewicht. Wörtlich: 200 Schekel Silber und einen Goldbarren von 50 Schekel Gewicht. Das waren noch keine Münzen, sondern Silberstücke mit festen Gewichtseinheiten. Ein Schekel entspricht etwa 11,5 Gramm."] },
      { number: 22, text: "Da schickte Josua einige Männer zu Achans Zelt. Sie fanden das Gestohlene, wie er es beschrieben hatte," },
      { number: 23, text: "nahmen es aus dem Zelt und brachten es zu Josua und dem ganzen Volk. Sie schütteten es vor Jahwe aus." },
      { number: 24, text: "Dann führten Josua und ganz Israel Achan Ben-Serach mitsamt dem Silber, dem Mantel und dem Goldbarren und dazu auch seine Söhne und Töchter, seine Rinder, Esel und Schafe, sein Zelt und alles, was ihm sonst noch gehörte, in das Tal Achor*.", footnotes: ["Achor. Das unfruchtbare Tal liegt in der Nähe von Jericho, wahrscheinlich an der Nordostgrenze von Juda, südlich von Jericho."] },
      { number: 25, text: "Dort sagte Josua: \"So, wie du uns ins Unglück gebracht hast, wird Jahwe heute dich ins Unglück bringen!\" Dann steinigte ganz Israel ihn und alles, was zu ihm gehörte. Anschließend verbrannten sie alles" },
      { number: 26, text: "und errichteten einen großen Steinhaufen darüber, der noch heute zu sehen ist. Da ließ Jahwe von seinem glühenden Zorn ab. Bis heute nennt man diesen Ort deshalb Tal Achor, Unglückstal." },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Nun sagte Jahwe zu Josua: \"Hab keine Angst und sei nicht niedergeschlagen! Nimm das ganze Heer mit und zieh nach Ai hinauf. Ich habe den König von Ai, sein Volk, seine Stadt und sein Gebiet in deine Hand gegeben.", heading: "Die Vernichtung von Ai" },
      { number: 2, text: "Du sollst mit Ai und seinem König dasselbe tun, was du mit Jericho und seinem König gemacht hast. Aber die Beute und das Vieh dürft ihr diesmal für euch behalten. Leg einen Hinterhalt im Rücken der Stadt!\"" },
      { number: 3, text: "Bevor sich Josua mit dem Heer auf den Weg machte, wählte er 30.000 erfahrene Kämpfer aus und schickte sie in der Nacht" },
      { number: 4, text: "mit folgender Anweisung los: \"Legt euch auf der anderen Seite der Stadt in einen Hinterhalt, aber nicht zu weit von ihr entfernt. Dort haltet euch bereit." },
      { number: 5, text: "Ich werde mit dem Hauptheer vor die Stadt ziehen. Wenn sie dann einen Ausfall machen wie beim ersten Mal, werden wir uns vor ihnen zurückziehen." },
      { number: 6, text: "Sie werden uns nachsetzen. Doch so werden wir sie von der Stadt abschneiden. Sie werden denken, dass wir wie beim ersten Mal vor ihnen fliehen." },
      { number: 7, text: "Wenn das geschieht, sollt ihr aus dem Hinterhalt hervorbrechen und die Stadt erobern. Jahwe, euer Gott, wird sie in eure Hand geben." },
      { number: 8, text: "Und wenn ihr dann die Stadt eingenommen habt, steckt sie in Brand, wie Jahwe es angeordnet hat. Haltet euch genau an meinen Befehl!\"" },
      { number: 9, text: "So hatte Josua sie losgeschickt. Sie umgingen die Stadt und legten sich im Westen zwischen Bet-El und Ai in den Hinterhalt. Josua aber verbrachte die Nacht beim Hauptheer." },
      { number: 10, text: "Früh am Morgen stand er auf, ließ das Volk antreten, stellte sich mit den Ältesten an die Spitze und führte das Heer gegen Ai." },
      { number: 11, text: "Sie näherten sich der Stadt von Norden her und rückten so nahe heran, dass nur noch ein Tal zwischen ihnen und Ai war." },
      { number: 12, text: "Josua hatte außerdem noch 5000 Mann westlich der Stadt in einen Hinterhalt zwischen Bet-El und Ai gelegt*.", footnotes: ["Hinterhalt ... gelegt. Das Heer sollte sicherstellen, dass die Einwohner von Bet-El keinen Überraschungsangriff von Nordwesten her führten, nicht aber dass sie sich an der Verfolgung der scheinbar fliehenden Israeliten beteiligten."] },
      { number: 13, text: "Das Hauptlager stand nördlich der Stadt, die Sperre* westlich. Noch in der Nacht rückte Josua auf die Talebene vor.", footnotes: ["Sperre. wörtlich: Ferse"] },
      { number: 14, text: "Als der König von Ai das sah, rückte er in aller Eile früh mit seinen Männern zum Kampf gegen Israel aus. Er wollte das Schlachtfeld in der Ebene erreichen, wusste aber nichts von dem Hinterhalt." },
      { number: 15, text: "Josua und die Männer Israels ließen sich von ihm schlagen und flohen in Richtung Wüste." },
      { number: 16, text: "Darauf wurden alle in der Stadt verbliebenen Männer aufgeboten, um die Fliehenden zu verfolgen. Sie jagten Josua nach und wurden dabei von der Stadt abgeschnitten." },
      { number: 17, text: "Nicht ein Mann war in Ai oder Bet-El* zurückgeblieben. Alle jagten hinter den Israeliten her und ließen die Stadt ohne Schutz mit offenen Toren zurück.", footnotes: ["oder Bet-El. Es gab offenbar einen Beistandspakt zwischen den benachbarten Städten."] },
      { number: 18, text: "Nun sagte Jahwe zu Josua: \"Strecke das Schwert in deiner Hand gegen Ai aus! Ich gebe die Stadt in deine Gewalt.\" Josua tat es." },
      { number: 19, text: "Sobald er seine Hand ausstreckte, brach der Hinterhalt aus seiner Stellung hervor. Die Männer überfielen die Stadt, eroberten sie und steckten sie schnell in Brand." },
      { number: 20, text: "Als die Männer von Ai zurückblickten, sahen sie den Rauch aus ihrer Stadt zum Himmel aufsteigen. Doch sie hatten keine Möglichkeit zur Flucht, sie konnten weder vor noch zurück, denn die Truppen, die zur Wüste hin geflohen waren, kehrten um und wandten sich gegen ihre Verfolger." },
      { number: 21, text: "Als Josua und die Israeliten nämlich sahen, dass der Rauch aus der Stadt aufstieg, machten sie kehrt und griffen die Männer von Ai an." },
      { number: 22, text: "Diese hatten ja ihre Stadt verlassen und sie verfolgt. Doch auf einmal waren sie von beiden Seiten eingeschlossen. Sie wurden vollständig aufgerieben. Keiner kam mit dem Leben davon." },
      { number: 23, text: "Den König von Ai hatten die Israeliten lebendig gefasst und zu Josua gebracht." },
      { number: 24, text: "Als sie dann alle ihre Gegner auf dem Schlachtfeld in der Wüste getötet hatten, drangen sie erneut in die Stadt ein und brachten alle Einwohner mit dem Schwert um." },
      { number: 25, text: "An diesem Tag starben alle Leute von Ai, etwa 12.000 Männer und Frauen." },
      { number: 26, text: "Josua hatte nämlich seine Hand mit dem ausgestreckten Langschwert nicht zurückgezogen, bis der Bann an allen Bewohnern von Ai vollstreckt war." },
      { number: 27, text: "Das Vieh und das sonstige Beutegut aus der Stadt behielten die Israeliten diesmal für sich, wie es Josua von Jahwe befohlen worden war." },
      { number: 28, text: "Josua ließ Ai vollständig niederbrennen und machte es für immer zu einem Schutthaufen*. Er ist noch heute zu sehen.", footnotes: ["Ai bedeutet Schutthaufen."] },
      { number: 29, text: "Den Leichnam des Königs von Ai ließ er bis zum Abend an einen Baum hängen. Bei Sonnenuntergang befahl Josua, ihn abzunehmen und in den Durchgang des Stadttores zu werfen. Die Männer Israels errichteten dann einen großen Steinhaufen über ihm, der noch heute zu sehen ist." },
      { number: 30, text: "Damals baute Josua auf dem Berg Ebal* Jahwe, dem Gott Israels, einen Altar,", heading: "Der Altar auf dem Ebal", footnotes: ["Ebal. nördlich von Sichem, 940 Meter hoch"] },
      { number: 31, text: "und zwar so, wie es Mose, der Diener Jahwes, den Israeliten befohlen hatte und wie es auch im Gesetzbuch des Mose steht. Es entstand ein Altar aus unbehauenen Steinen, die noch kein eisernes Werkzeug berührt hatte. Auf diesem Altar brachten die Israeliten Jahwe Brandopfer dar und aßen von den Freudenopfern.*", footnotes: ["Beim Freudenopfer (wörtlich Friedens- oder Heilsopfer) durfte der größte Teil des Tieres bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 32, text: "Auf die Steine dort schrieb Josua in Gegenwart des Volkes eine Abschrift vom Gesetz des Mose nieder." },
      { number: 33, text: "Dann stellte sich das ganze Volk Israel mit seinen Ältesten, Anführern und Richtern sowie den Fremden, die sich ihnen angeschlossen hatten, auf beiden Seiten der Bundeslade auf. Die eine Hälfte stand mit dem Rücken zum Berg Garizim* und die andere zum Berg Ebal. Zwischen ihnen, an der Bundeslade Jahwes, standen die Priester aus dem Stamm Levi, die die Lade trugen. So sollte das Volk Israel nach der Anweisung von Mose, dem Diener Jahwes, gesegnet werden.", footnotes: ["Garizim. Südlich vom Ebal, 881 Meter hoch, 50 km nördlich von Jerusalem."] },
      { number: 34, text: "Danach las Josua das ganze Gesetz laut vor, den Segen wie den Fluch, genauso wie es im Gesetzbuch geschrieben steht." },
      { number: 35, text: "Er ließ kein einziges Wort davon aus. Die ganze Versammlung Israels, auch die Frauen, die Kinder und die Fremden, die bei ihnen lebten, hörten jedes Wort, das Mose befohlen hatte." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Alle Könige im Westjordanland hörten von den Siegen Israels, ob sie im Gebirge, in der Schefela* oder in der Küstenebene des Mittelmeeres bis zum Libanon hin lebten, die Hetiter, die Amoriter, die Kanaaniter, die Perisiter, die Hiwiter und die Jebusiter.", heading: "Die List der Gibeoniten", footnotes: ["Schefela. Niedriges, sehr fruchtbares Hügelland, das sich in nordsüdlicher Richtung zwischen dem Gebirge und der Küstenebene des Mittelmeeres erstreckt."] },
      { number: 2, text: "Da taten sie sich zusammen, um gemeinsam gegen Josua und Israel zu kämpfen." },
      { number: 3, text: "Als die Einwohner von Gibeon* jedoch hörten, was Josua mit Jericho und Ai gemacht hatte,", footnotes: ["Gibeon. Die Stadt liegt 9 km nordwestlich von Jerusalem."] },
      { number: 4, text: "griffen sie zu einer List. Sie wollten sich als Boten ausgeben. Deshalb nahmen sie abgenutzte Säcke für ihre Esel und abgenutzte und geflickte Weinschläuche" },
      { number: 5, text: "und zogen zerschlissene und geflickte Schuhe und abgetragene Kleidung an. Das Brot, das sie als Wegzehrung dabeihatten, war vertrocknet und zerbröselt." },
      { number: 6, text: "So kamen sie ins Lager nach Gilgal. \"Wir kommen aus einem fernen Land\", sagten sie zu Josua und den Männern von Israel, \"und möchten, dass ihr einen Bund mit uns schließt.\"" },
      { number: 7, text: "Da sagten die Israeliten zu den Hiwitern*: \"Wir können doch nicht einfach ein Bündnis mit euch schließen. Vielleicht wohnt ihr ja ganz in unserer Nähe.\"", footnotes: ["Hiwiter. Siehe Fußnote zu Josua 3,10."] },
      { number: 8, text: "\"Wir sind deine Diener\", sagten sie zu Josua. Der fragte: \"Wer seid ihr und woher kommt ihr?\"" },
      { number: 9, text: "\"Deine Diener kommen aus einem sehr weit entfernten Land, weil der Ruhm von Jahwe, deinem Gott, bis zu uns gedrungen ist. Wir haben alles gehört, was er in Ägypten getan hat," },
      { number: 10, text: "und auch das, was er mit den beiden Amoriterkönigen im Ostjordanland gemacht hat, mit König Sihon von Heschbon* und König Og von Baschan*, der in Aschtarot* lebte.", footnotes: ["Heschbon. Stadt, 25 km östlich der Jordanmündung ins Tote Meer, 19 km südwestlich von Rabba (heute Amman).", "Baschan. Gebiet östlich und nördlich vom See Gennesaret.", "Aschtarot. 35 km östlich vom See Gennesaret, später Levitenstadt."] },
      { number: 11, text: "Da sagten unsere Ältesten und alle Bewohner des Landes zu uns: 'Nehmt Verpflegung mit auf den Weg, zieht ihnen entgegen und sagt zu ihnen: Wir sind eure Diener, schließt einen Bund mit uns!'" },
      { number: 12, text: "Hier, seht euch das Brot an! Es war noch warm, als wir von zu Hause aufbrachen. Jetzt ist es vertrocknet und zerbröselt." },
      { number: 13, text: "Und diese zerrissenen Weinschläuche hier waren neu, als wir sie füllten. Auch unsere Kleidung und die Schuhe sind durch die lange Reise verschlissen.\"" },
      { number: 14, text: "Die Israeliten untersuchten das Brot, aber sie versäumten es, Jahwe zu befragen." },
      { number: 15, text: "So gewährte Josua ihnen Frieden und sicherte zu, sie am Leben zu lassen. Die Führer des Volkes bekräftigten den Vertrag mit einem Eid." },
      { number: 16, text: "Drei Tage später kam es heraus, dass sie ganz in ihrer Nähe wohnten." },
      { number: 17, text: "Die Israeliten waren nämlich weitergezogen und auf die Städte gestoßen, aus denen die Boten gekommen waren: Gibeon, Kefira, Beerot und Kirjat-Jearim." },
      { number: 18, text: "Doch sie konnten ihnen nichts antun, weil die Führer des Volkes ihnen im Namen Jahwes Frieden geschworen hatten. Da murrte die ganze Volksversammlung über ihre Führer." },
      { number: 19, text: "Die verteidigten sich: \"Wir haben ihnen im Namen Jahwes Frieden geschworen und können sie jetzt nicht antasten." },
      { number: 20, text: "Wir müssen sie am Leben lassen, damit kein Zorngericht wegen des Eides über uns kommt.\"" },
      { number: 21, text: "Aber sie sicherten den Israeliten zu, die Hiwiter zu Holzhauern und Wasserträgern für ganz Israel zu machen." },
      { number: 22, text: "Dann bestellte Josua die Boten aus Gibeon zu sich und sagte zu ihnen: \"Warum habt ihr uns getäuscht und behauptet, von sehr weit her zu kommen, wo ihr doch ganz in unserer Nähe wohnt?" },
      { number: 23, text: "Darum sollt ihr verflucht und für alle Zeit Sklaven für das Haus meines Gottes sein – Holzhauer und Wasserträger!\"" },
      { number: 24, text: "Sie antworteten Josua: \"Deinen Dienern wurde zuverlässig berichtet, dass Jahwe, dein Gott, seinem Diener Mose geboten habe, euch das ganze Land zu geben und alle seine Bewohner zu töten. Darum fürchteten wir sehr um unser Leben." },
      { number: 25, text: "Nun, wir sind in deiner Hand; mach mit uns, was du für richtig hältst.\"" },
      { number: 26, text: "Josua stand zu seinem Wort und bewahrte die Gibeoniten davor, von den Männern Israels getötet zu werden." },
      { number: 27, text: "Doch verpflichtete er sie an diesem Tag zum Dienst am Altar Jahwes als Holzhauer und Wasserträger. Sie tun das noch heute an dem Ort, den Jahwe für seinen Altar erwählt hat." },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Als Adoni-Zedek, der König von Jerusalem, und seine Leute hörten, dass Josua Ai erobert und zerstört hatte, dass dessen König dasselbe Schicksal erlitten hatte wie der König von Jericho und dass die Bewohner von Gibeon mit Israel Frieden geschlossen hatten und nun zu ihnen gehörten,", heading: "Israel kämpft für Gibeon" },
      { number: 2, text: "bekamen sie es mit der Angst zu tun. Gibeon war ja so groß wie eine Königsstadt, größer als Ai, und seine Männer waren als tapfere Krieger bekannt." },
      { number: 3, text: "Da schickte Adoni-Zedek Boten zu den Nachbarkönigen Hoham von Hebron*, Piram von Jarmut*, Jafia von Lachisch* und Debir von Eglon* und ließ ihnen ausrichten:", footnotes: ["Hebron. Die Stadt liegt etwa 35 km südlich von Jerusalem und 30 km westlich vom Toten Meer.", "Jarmut. Stadt in der Schefela, 5 km südlich von Bet-Schemesch.", "Lachisch. Wichtige kanaanäische Königsstadt, seit dem 3. Jahrtausend v.Chr. besiedelt, 25 km westlich von Hebron.", "Eglon. Vermutlich 10 km westlich von Lachisch."] },
      { number: 4, text: "\"Die Leute von Gibeon haben mit Josua und den Israeliten Frieden geschlossen. Kommt und helft mir, sie zu bestrafen!\"" },
      { number: 5, text: "Da vereinigten sich die fünf Amoriterkönige und zogen mit ihrer ganzen Heeresmacht vor Gibeon. Sie erklärten Gibeon den Krieg und begannen die Stadt zu belagern." },
      { number: 6, text: "Da schickten die Männer von Gibeon Boten nach Gilgal ins Lager der Israeliten und baten Josua: \"Lass deine Diener jetzt nicht im Stich! Komm schnell zur Hilfe und rette uns! Alle Amoriterkönige aus dem Bergland belagern unsere Stadt.\"" },
      { number: 7, text: "Da rief Josua die kriegstüchtigen Männer von Israel zusammen und brach mit dem Heer von Gilgal auf." },
      { number: 8, text: "Und Jahwe sagte zu Josua: \"Fürchte dich nicht vor ihnen, denn ich habe sie alle in deine Hand gegeben. Niemand wird vor dir standhalten können.\"" },
      { number: 9, text: "Als Josua die Amoriter nun plötzlich überfiel – die ganze Nacht hindurch waren sie von Gilgal aus marschiert –" },
      { number: 10, text: "ließ Jahwe unter ihnen einen Schrecken vor Israel entstehen, und Josua konnte ihnen bei Gibeon eine schwere Niederlage beibringen. Er verfolgte sie bis zur Steige von Bet-Horon* und noch weiter bis nach Aseka* und Makkeda*.", footnotes: ["Steige von Bet-Horon. Wichtiger Passweg vom Gebirge in die Schefela Judas, der von den Orten Oberes Bet-Horon (617 Meter ü. NN) und Unteres Bet-Horon (399 Meter ü. NN) beherrscht wird.", "Aseka. 9 km östlich von Gat, 24 km nordwestlich von Hebron.", "Makkeda. Vermutlich Kirbet el-Kum, 14 km westlich von Hebron."] },
      { number: 11, text: "Und als sie die Steige von Bet-Horon hinabflohen und auf dem ganzen Weg nach Aseka, ließ Jahwe große Steine vom Himmel auf sie herabfallen. Es kamen mehr durch die Hagelsteine um, als die Israeliten mit dem Schwert töteten." },
      { number: 12, text: "Damals hatte Josua zu Jahwe gebetet – es war an dem Tag, als Jahwe ihnen die Amoriter auslieferte – und hatte dann vor den Israeliten gesagt:\"Sonne halt still über Gibeon / und Mond überm Tal von Ajalon*!\"", footnotes: ["Ajalon. Stadt in der Schefela, 21 km nordwestlich von Jerusalem."] },
      { number: 13, text: "Da hielt die Sonne still, und auch der Mond blieb stehen, bis das Volk sich an seinen Feinden gerächt hatte. So wird es auch im Buch der Heldenlieder* beschrieben. Die Sonne blieb mitten am Himmel stehen und beeilte sich nicht unterzugehen, ungefähr einen ganzen Tag lang.", footnotes: ["Buch der Heldenlieder. Hebräisch: Buch Jaschar. Wörtlich: Buch des Redlichen, vermutlich eine Sammlung von Liedern auf die Helden Israels."] },
      { number: 14, text: "Weder vorher noch nachher hat es solch einen Tag gegeben, dass Jahwe auf das Gebet eines Menschen hin so etwas gewirkt hätte. Doch damals kämpfte Jahwe selbst für Israel." },
      { number: 15, text: "Nach dem Sieg kehrte Josua mit dem ganzen Heer ins Lager nach Gilgal zurück." },
      { number: 16, text: "Die fünf Amoriterkönige jedoch waren entkommen und hatten sich in einer Höhle bei Makkeda versteckt." },
      { number: 17, text: "Das wurde Josua noch während der Schlacht gemeldet," },
      { number: 18, text: "und er hatte befohlen, große Steine an den Eingang der Höhle zu wälzen und sie mit einigen Wachtposten zu sichern." },
      { number: 19, text: "Zu den anderen aber hatte er gesagt: \"Bleibt nicht stehen, sondern verfolgt die Feinde, und macht auch noch die Nachhut nieder! Lasst sie nicht in ihre Städte entkommen, denn Jahwe, euer Gott, hat sie euch in die Hand gegeben!\"" },
      { number: 20, text: "So brachten Josua und die Männer Israels den Amoritern eine vernichtende Niederlage bei. Nur wenige konnten entkommen und die festen Städte erreichen." },
      { number: 21, text: "Dann kehrte das Heer wohlbehalten zu Josua ins Feldlager bei Makkeda zurück. Jetzt wagte niemand mehr, den Mund gegen die Israeliten aufzumachen." },
      { number: 22, text: "Dann befahl Josua: \"Öffnet den Höhleneingang und bringt die fünf Könige zu mir heraus!\"" },
      { number: 23, text: "Man wälzte die Steine beiseite und brachte die Könige von Jerusalem, von Hebron, von Jarmut, von Lachisch und von Eglon heraus." },
      { number: 24, text: "Als sie vor Josua standen, rief dieser alle Männer Israels herbei und sagte zu den Anführern des Heeres: \"Kommt her und setzt euren Fuß auf den Nacken dieser Könige!\" Als sie das taten," },
      { number: 25, text: "sagte Josua zu ihnen: \"Ihr müsst euch vor niemand fürchten! Lasst euch nicht einschüchtern, seid mutig und entschlossen! So wird es Jahwe mit allen euren Feinden machen, gegen die ihr kämpft.\"" },
      { number: 26, text: "Danach ließ Josua die Könige töten und ihre Leichen bis zum Abend an fünf Bäume hängen." },
      { number: 27, text: "Als die Sonne unterging, ließ er sie abnehmen und in die Höhle werfen, in der sie sich versteckt hatten. Dann wälzten sie große Steine vor den Eingang. Sie liegen heute noch dort." },
      { number: 28, text: "Noch am selben Tag eroberte Josua die Stadt Makkeda und ließ alles Lebendige mit dem Schwert umbringen. Er vollstreckte an ihr und ihrem König den Bann wie bei dem König von Jericho.", heading: "Die Eroberung von Süd-Kanaan" },
      { number: 29, text: "Dann führte Josua das israelitische Heer von Makkeda nach Libna* und griff auch diese Stadt an.", footnotes: ["Libna. Stadt in der Schefela, vermutlich 13 km nordöstlich von Lachisch."] },
      { number: 30, text: "Jahwe gab sie und ihren König in die Hand Israels. Alles Leben darin wurde mit dem Schwert getötet, und sein König fand das gleiche Ende wie der von Jericho." },
      { number: 31, text: "Danach zog Josua mit dem Heer nach Lachisch und belagerte die Stadt." },
      { number: 32, text: "Jahwe gab auch sie in die Hand Israels. Am zweiten Tag eroberten sie die Stadt und erschlugen alles Lebendige darin mit dem Schwert, wie sie es in Libna gemacht hatten." },
      { number: 33, text: "Als dann König Horam von Geser* mit seinen Männern heraufzog, um Lachisch zu helfen, wurde er von Josua vernichtend geschlagen. Keiner entkam.", footnotes: ["Geser. Stadt im nördlichen Teil der Schefela, 27 km südöstlich von Joppe."] },
      { number: 34, text: "Von Lachisch führte Josua das Heer nach Eglon. Sie umzingelten die Stadt," },
      { number: 35, text: "nahmen sie noch am selben Tag ein und vollstreckten wie in Lachisch an allem Lebendigen den Bann." },
      { number: 36, text: "Von Eglon aus zogen sie nach Hebron hinauf und griffen es an." },
      { number: 37, text: "Sie eroberten die Stadt und erschlugen die Bewohner samt ihrem König. Auch an den dazugehörenden Ortschaften vollstreckten sie den Bann und vernichteten alles Leben darin." },
      { number: 38, text: "Dann wandte sich Josua von Hebron ab und griff mit dem Heer Israels Debir* an.", footnotes: ["Debor. 14 km südwestlich von Hebron."] },
      { number: 39, text: "Er nahm die Stadt und die dazugehörigen Orte ein und ließ wie in Hebron an allem Lebendigen den Bann vollstrecken und wie in Libna auch den König töten." },
      { number: 40, text: "So eroberte Josua das ganze Land, das Gebirge, den Negev im Süden, die Schefela und die östlichen Berghänge*. Keiner, der dort lebte, entging dem Gericht Gottes. An allem vollstreckte er den Bann, wie es Jahwe, Israels Gott, befohlen hatte.", footnotes: ["östliche Berghänge. Offenbar die Abhänge zum Toten Meer hin."] },
      { number: 41, text: "Das eroberte Land reichte von Kadesch-Barnea* bis nach Gaza*, von der Landschaft Goschen* bis nach Gibeon.", footnotes: ["Kadesch-Barnea. Ort an der Südgrenze Kanaans, etwa 80 km südwestlich von Beerscheba.", "Gaza. Bedeutendste Stadt der Philister, 6 km vom Mittelmeer entfernt.", "Goschen. Nach Josua 15,51eine Stadt und ein Gebiet in Südkanaan, bisher nicht identifiziert. Nicht zu verwechseln mit Goschen in Ägypten (1. Mose 45,10)."] },
      { number: 42, text: "Weil Jahwe, der Gott Israels, für sein Volk kämpfte, konnte Josua in einem einzigen Feldzug alle Könige dort besiegen und ihr Land erobern." },
      { number: 43, text: "Dann kehrte Josua mit dem Heer Israels ins Lager nach Gilgal zurück." },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Als Jabin, der König von Hazor*, das hörte, schickte er Boten zu König Jobab von Madon*, zu den Königen von Schimron* und Achschaf*,", heading: "Der nördliche Feldzug", footnotes: ["Hazor. Wichtigste kanaanitische Festung im Norden, 14 km nördlich vom See Gennesaret.", "Madon. Galiläische Stadt, vielleicht identisch mit Merom, 12 km nordwestlich von Hazor.", "Schimron. Galiläische Stadt, 15 km westlich vom Berg Tabor.", "Achschaf. Galiläische Stadt, 16 km südlich von Akko."] },
      { number: 2, text: "zu den Königen im nördlichen Bergland, in der Ebene südlich von Kinneret*, in der Schefela und im Küstengebiet von Dor*,", footnotes: ["Kinneret. Früherer Name des Sees Gennesaret und einer Ortschaft an seinem Westufer.", "Dor. Hafenstadt am Mittelmeer, 13 km nördlich von Cäsarea."] },
      { number: 3, text: "zu den Kanaanitern im Osten und Westen, zu den Amoritern, den Hetitern, den Perisitern und den Jebusitern im Gebirge und zu den Hiwitern am Fuß des Hermon* im Gebiet von Mizpa*.", footnotes: ["Hermon. Drei fast gleich hohe (über 2800 Meter) schneebedeckte Gipfel im Libanon. Der Hermon wurde von den vorisraelischen Bewohnern als heilig verehrt, deshalb auch Baal-Hermon genannt.", "Mizpa. Offenbar identisch mit Mizpe in V. 8. Gebiet im Südlibanon."] },
      { number: 4, text: "Alle diese Könige brachen mit ihren Truppen auf, es war eine riesige Menge, unzählbar wie der Sand am Meeresstrand; und sie hatten sehr viele Pferde und Streitwagen* dabei.", footnotes: ["Streitwagen. Einachsige, von Pferden gezogene schnelle Wagen, die von einem Wagenlenker, einem Bogeschützen und evtl. noch einem Schildhalter besetzt waren – die Panzer des Altertums."] },
      { number: 5, text: "Ihr gemeinsames Feldlager zum Kampf gegen Israel schlugen sie am Wasser von Merom* auf.", footnotes: ["Merom. Wahrscheinlich 13 km südwestlich von Hazor, in einer waldreichen Gegend unter dem Har-Merom (1208 Meter), dem höchsten Berg Nordgaliläas."] },
      { number: 6, text: "Da sagte Jahwe zu Josua: \"Hab keine Angst vor ihnen! Ich werde dafür sorgen, dass ihr sie morgen um diese Zeit alle erschlagen habt. Du wirst ihre Pferde lähmen* und ihre Streitwagen in Brand stecken!\"", footnotes: ["Pferde lähmen. Man durchschnitt ihnen die Fußsehnen."] },
      { number: 7, text: "Josua führte Israels Heer zu einem Überraschungsangriff auf das feindliche Lager am Wasser von Merom," },
      { number: 8, text: "und Jahwe gab sie in ihre Hand. Sie schlugen sie in die Flucht und verfolgten sie bis zu der großen Stadt Sidon*, bis nach Misrefot-Majim* und in die Talebene von Mizpe* im Osten. Keiner der Fliehenden entkam.", footnotes: ["Sidon. Wichtigste Hafenstadt Phöniziens, 40 km nördlich von Tyrus. Ihre Einwohner und die der Umgebung werden Sidonier genannt.", "Misferot-Majim. Das meint vielleicht das Gebiet des Flusses Litani im Libanon.", "Mizpe. Gegend in der Nähe des Hermon"] },
      { number: 9, text: "Nach Jahwes Befehl ließ Josua ihre Pferde lähmen und die Streitwagen verbrennen." },
      { number: 10, text: "Dann kehrte er um und eroberte Hazor, die Hauptstadt dieser Vereinigung von Stadtkönigen, und erschlug ihren König." },
      { number: 11, text: "An allem Lebendigen ließ er den Bann vollstrecken. Alle Bewohner wurden mit dem Schwert getötet, und die Stadt wurde in Brand gesteckt." },
      { number: 12, text: "Auch alle anderen Städte dieser Vereinigung eroberte Josua und vollstreckte an ihren Königen und Einwohnern den Bann, wie es Mose, der Diener Jahwes, befohlen hatte." },
      { number: 13, text: "Niederbrennen ließ Josua aber nur Hazor. Die anderen Städte auf den Hügeln ließ er stehen." },
      { number: 14, text: "Die Beute aus diesen Städten und das Vieh nahmen die Israeliten für sich, aber von den Menschen ließen sie niemand am Leben. Sie vernichteten sie völlig und erschlugen alle mit dem Schwert." },
      { number: 15, text: "Wie Jahwe es seinem Diener Mose befohlen hatte, so trug Mose es Josua auf. Und Josua hielt sich genau an alle Weisungen, die Mose von Jahwe bekommen hatte.", heading: "Die eroberten Gebiete" },
      { number: 16, text: "Josua nahm das ganze Land ein, das Gebirge, den ganzen Negev und ganz Goschen, die Schefela, die Jordantiefebene und das Bergland Israels," },
      { number: 17, text: "alles Land vom kahlen Berg Seïr* bis hin nach Baal-Gad* im Libanontal am Fuß des Hermon. Alle Könige, die dort regierten, nahm er gefangen und tötete sie.", footnotes: ["Seïr heißt eigentlich bewaldet und meint hier wohl einen Berg in Juda (sonst ein Gebirge in Edom).", "Baal-Gad. Stadt im Libanontal."] },
      { number: 18, text: "Er musste jedoch lange gegen sie kämpfen," },
      { number: 19, text: "denn außer der Hiwiterstadt Gibeon ergab sich keine Stadt den Israeliten freiwillig. Alle mussten sie im Kampf erobern." },
      { number: 20, text: "Jahwe hatte sie starrsinnig zum Krieg gegen Israel gemacht, damit er den Bann an ihnen vollstrecken konnte. Es sollte keine Gnade für sie geben. Israel musste sie vernichten, wie Jahwe es Mose befohlen hatte." },
      { number: 21, text: "Damals vernichtete Josua auch die Anakiter*, die im Gebirge, in Hebron, Debir und Anab* wohnten, und in allen anderen Städten im Gebirge Juda und Israel. Josua vollstreckte den Bann an ihnen,", footnotes: ["Anakiter Eine Sippe von riesenhaften Menschen in der Umgebung von Hebron, siehe 4. Mose 13,33.", "Anab. Stadt 20 km südwestlich von Hebron."] },
      { number: 22, text: "sodass in dem eroberten Land niemand von ihnen übrig blieb. Nur in Gaza, Gat* und Aschdod* entkamen sie dem Untergang.", footnotes: ["Gat. Eine der fünf Philisterstädte, spätere Heimatstadt des Goliat.", "Aschdod. Bedeutende Philisterstadt, 5 km vom Mittelmeer entfernt."] },
      { number: 23, text: "So eroberte Josua das ganze Land, wie es Jahwe zu Mose gesagt hatte, und gab es Israel zum Eigentum, jedem Stamm sein Gebiet. Das Land hatte nun Ruhe vor dem Krieg." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Die Israeliten hatten folgende Könige besiegt und deren Land im Ostjordangebiet vom Fluss Arnon* bis zum Berg Hermon in Besitz genommen, einschließlich der ganzen östlichen Jordantiefebene:", heading: "Die besiegten Könige", footnotes: ["Arnon. Fluss, etwa 44 km lang, mündet ins Tote Meer. Er bildete die Südgrenze Israels im Ostjordangebiet."] },
      { number: 2, text: "Zunächst den Amoriterkönig Sihon aus Heschbon. Er herrschte von Aroër* am Arnon, von der Mitte des Arnontals an über das halbe Gilead* bis zum Fluss Jabbok, wo das Gebiet der Ammoniter* beginnt,", footnotes: ["Aroër. Stadt am Nordufer des Arnon, 23 km östlich des Toten Meeres.", "Gilead. Landschaft östlich des Jordan, Wohnsitz der Stämme Ruben, Gad und halb Manasse.", "Ammoniter. nordöstliche Nachbarn der Moabiter"] },
      { number: 3, text: "über das östliche Jordantal bis an den See Kinneret und nach Süden zu bis an das Meer der Araba, das Salzmeer, und bis nach Bet-Jeschimot* und den Abhängen des Berges Pisga*.", footnotes: ["Bet-Jeschimot. Letzter Lagerplatz Israels vor dem Zug durch den Jordan (4. Mose 33,49), 7 km nordöstlich vom Toten Meer.", "Pisga. Wahrscheinlich in der Nähe des Nebo, 14 km östlich vom Nordende des Toten Meeres."] },
      { number: 4, text: "Dann das Land des Königs Og von Baschan, dem letzten vom Geschlecht der Refaïter*, der in Aschtarot und Edreï* regierte.", footnotes: ["Refaiter. Volksstamm von außergewöhnlich hohem Wuchs.", "Edreï. Die Residenzstadt lag 96 km südlich von Damaskus und 50 km östlich vom Jordan."] },
      { number: 5, text: "Er herrschte über das Hermongebirge, über das Gebiet von Salcha* und Baschan bis an die Grenze zu den Königreichen Geschur* und Maacha* und über die andere Hälfte Gileads bis an die Grenze von König Sihons Herrschaftsgebiet.", footnotes: ["Salcha. Die Stadt liegt etwa 100 km südöstlich vom See Gennesaret.", "Geschur. Kleines syrisches Königreich nördlich und östlich vom See Gennesaret, das unabhängig von Israel blieb.", "Maacha. Kleines syrisches Königreich im Norden Israels, dessen Gebiet dem halben Stamm Manasse zugeteilt wurde, obwohl die Einwohner nicht vertrieben wurden."] },
      { number: 6, text: "Diese beiden Könige waren unter der Führung Moses von den Israeliten besiegt worden. Und Mose, der Diener Jahwes, gab ihr Land den Stämmen Ruben, Gad und dem halben Stamm Manasse als Erbbesitz." },
      { number: 7, text: "Es folgen die Könige, die unter der Führung Josuas von den Israeliten im Westjordanland besiegt worden sind, und zwar von Baal-Gad am Fuß des Libanon-Gebirges bis zum kahlen Berg Seïr. Josua gab es den Stämmen Israels zum Besitz:" },
      { number: 8, text: "das Gebirge, die Schefela, die Abhänge zur Araba hin mit der Wüste Juda und den Negev im Süden, das ganze Gebiet der Hetiter, Amoriter, Kanaaniter, Perisiter, Hiwiter und Jebusiter." },
      { number: 9, text: "Es waren der König von Jericho, der König von Ai, das neben Bet-El liegt," },
      { number: 10, text: "der König von Jerusalem, der König von Hebron," },
      { number: 11, text: "der König von Jarmut und der von Lachisch," },
      { number: 12, text: "der König von Eglon und der von Geser;" },
      { number: 13, text: "der König von Debir und der von Geder," },
      { number: 14, text: "der von Horma* und der von Arad*,", footnotes: ["Horma. Ort im Umkreis von Beerscheba.", "Arad. Stadt, 27 km südlich von Hebron."] },
      { number: 15, text: "der von Libna und der von Adullam*;", footnotes: ["Adullam. Stadt in der Schefela, 26 km westlich von Jerusalem."] },
      { number: 16, text: "der König von Makkeda und der von Bet-El," },
      { number: 17, text: "der von Tappuach und der von Hefer*,", footnotes: ["Hefer. Stadt, 40 km nördlich von Joppe in der Nähe der Mittelmeerküste."] },
      { number: 18, text: "der von Afek* und der von Scharon;", footnotes: ["Afek. Stadt in der Scharon-Ebene, 18 km östlich von Joppe."] },
      { number: 19, text: "der König von Madon, der von Hazor," },
      { number: 20, text: "der von Schimron-Meron* und der von Achschaf;", footnotes: ["Meron. Vermutlich ist Schimron gemeint, 15 km nördlich von Megiddo."] },
      { number: 21, text: "der König von Taanach*, der von Megiddo*,", footnotes: ["Taanach. Die Stadt liegt 6 km südöstlich von Megiddo.", "Megiddo. Bedeutende kanaanitische Stadt am Südwestrand des Jesreel-Tales. Die Festung bewachte einen wichtigen Pass, der durch die Karmel-Bergkette verlief."] },
      { number: 22, text: "der von Kedesch* und der von Jokneam* am Karmel*;", footnotes: ["Kedesch in Galiläa, 27 km nördlich vom See Gennesaret.", "Jokneam. 11 km nordwestlich von Megiddo.", "Karmel. Berg, der die Mittelmeerebene unterbricht, Symbol für Schönheit und Fruchtbarkeit."] },
      { number: 23, text: "der König von Dor im Hügelland von Dor, der König von Haroschet-Gojim in Galiläa*", footnotes: ["Haroschet-Gojim in Galiläa. Vermutlich Ort im Jesreel-Tal, wörtlich: Gojim in Gilgal, was aber unverständlich ist."] },
      { number: 24, text: "und der König von Tirza*. Insgesamt 31 Könige.", footnotes: ["Triza. 10 km nordöstlich von Sichem."] },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Inzwischen war Josua sehr alt geworden. Da sagte Jahwe zu ihm: \"Du bist schon sehr alt, und sehr viel Land ist noch in Besitz zu nehmen.", heading: "13-21: Die Verteilung des Landes\nNoch nicht eroberte Gebiete" },
      { number: 2, text: "Folgende Gebiete sind noch zu erobern: Alle Bezirke der Philister* und ganz Geschur,", footnotes: ["Die Philister bewohnten die südliche Küstenebene von Kanaan."] },
      { number: 3, text: "das Gebiet vom Schihor* vor Ägypten bis zur Grenze von Ekron* im Norden, das den Kanaanitern zugerechnet wird, die fünf Fürstentümer der Philister: Gaza, Aschdod, Aschkelon, Gat und Ekron und das Gebiet der Awiter*", footnotes: ["Schihor. Einer der Nilkanäle in der Nähe des heutigen Suez-Kanals.", "Ekron. Philisterstadt in der Küstenebene, 32 km südöstlich von Joppe.", "Awiter. Volk in der Nähe von Gaza."] },
      { number: 4, text: "im Süden. Weiter gehört dazu das ganze Gebiet der Kanaaniter von der Sidonierstadt Meara bis nach Afek und zur Grenze der Amoriter;" },
      { number: 5, text: "das Gebiet der Gebaliter* und der ganze Libanon im Osten von Baal-Gad am Fuß des Hermon bis dorthin, wo es nach Hamat* geht;", footnotes: ["Geba ist eine Stadt an der phönizischen Küste, 60 km nördlich von Sidon.", "Hamat. heute: Labwe, etwa 70 km nördlich vom Berg Hermon."] },
      { number: 6, text: "alle Gebirgsbewohner vom Libanon an bis nach Misrefot-Majim, alle Sidonier. Ich selbst werde sie vor den Israeliten vertreiben. Verlose ruhig das ganze Land als Erbbesitz für Israel, wie ich es dir befohlen habe." },
      { number: 7, text: "Verteile es als bleibenden Besitz an die neun Stämme und den halben Stamm Manasse.\"" },
      { number: 8, text: "Die andere Hälfte des Stammes Manasse hatte zusammen mit den Rubeniten und Gaditen ihren Erbbesitz schon im Ostjordanland angenommen, so wie Mose, der Diener Jahwes, es ihnen ausgeteilt hat:", heading: "Das schon eroberte Gebiet (13-17)\nDas Ostjordanland" },
      { number: 9, text: "von Aroer am Rand des Arnontals an und der Stadt, die direkt am Fluss liegt; die ganze Hochebene zwischen Medeba* und Dibon*", footnotes: ["Medeba. Moabitische Stadt, 32 km südlich vom heutigen Amman.", "Dibon. Bedeutende Stadt Moabs, 21 km östlich vom Toten Meer, 5 km nördlich der Arnon-Schlucht."] },
      { number: 10, text: "und alle Städte des Amoriterkönigs Sihon, der von Heschbon aus geherrscht hatte bis zur ammonitischen Grenze;" },
      { number: 11, text: "die Landschaft Gilead und das Land der Geschuriter, das Land der Maachatiter und das ganze Hermongebirge, ganz Baschan bis nach Salcha;" },
      { number: 12, text: "das ganze Reich von König Og, der in Aschtarot und Edreï regierte, der Letzte aus dem Geschlecht der Refaïter, die von Mose geschlagen und vertrieben worden waren." },
      { number: 13, text: "Aber die Geschuriter und Maachatiter vertrieben die Israeliten nicht. Sie leben bis heute mitten in Israel." },
      { number: 14, text: "Nur dem Stamm Levi gab Mose keinen Erbbesitz. Ihm wurden die Opfergaben für Jahwe, den Gott Israels, als Anteil zugesichert." },
      { number: 15, text: "Den Sippen des Stammes Ruben hatte Mose folgendes Gebiet zugeteilt:" },
      { number: 16, text: "von Aroer an, das am Rand des Arnontals liegt, und der Stadt direkt am Fluss, über die ganze Hochebene bis Medeba" },
      { number: 17, text: "und Heschbon mit all den Städten des Hochlandes: Dibon, Bamot-Baal*, Bet-Baal-Meon*,", footnotes: ["Bamot-Baal. Nordöstlich des Toten Meeres. Genaue Ortslage unbekannt.", "Bet-Baal-Meon. 10 km östlich vom Toten Meer, 37 km südwestlich vom heutigen Amman."] },
      { number: 18, text: "Jahaz*, Kedemot*, Mefaat*,", footnotes: ["Jahaz. Moabitische Stadt auf der Hochfläche des Ostjordanlandes, 17 km südöstlich von Medeba.", "Kedemot. 32 km östlich vom Toten Meer, nördlich des Arnon.", "Mefat. Vielleicht identisch mit Jahwah, 11 km südlich vom heutigen Amman."] },
      { number: 19, text: "Kirjatajim*, Sibma, Zeret-Schahar im Bergland östlich des Salzmeeres und", footnotes: ["Kirjatajom. Vielleicht 14 km östlich vom Toten Meer."] },
      { number: 20, text: "Bet-Peor*. Dazu kamen die Siedlungen auf den Abhängen des Pisga, Bet-Jeschimot", footnotes: ["Bet-Peor. 29 km westlich vom heutigen Amman."] },
      { number: 21, text: "und alle anderen Städte der Hochebene. Es umfasste das ganze Herrschaftsgebiet des Amoriterkönigs Sihon aus Heschbon, den Mose ebenso besiegt hatte wie die midianitischen* Stammesfürsten: Ewi, Rekem, Zur, Hur und Reba, die dort lebten und in Sihons Diensten standen.", footnotes: ["Die Midianiter waren ein Nomadenvolk, das in der Araba (Jordantal) und in Transjordanien umherzog."] },
      { number: 22, text: "Neben vielen anderen töteten die Israeliten damals auch den Wahrsager Bileam Ben-Beor* mit dem Schwert.", footnotes: ["Bileam Ben-Beor. Siehe 4. Mose 22-24."] },
      { number: 23, text: "Die Westgrenze des Stammes Ruben bildete der untere Jordan und seine Uferlandschaft. Diese Städte und Dörfer waren den Sippen des Stammes Ruben zugeteilt worden." },
      { number: 24, text: "Den Sippen des Stammes Gad hatte Mose folgendes Gebiet zugeteilt:" },
      { number: 25, text: "Jaser* und alle Städte Gileads, das halbe Land der Ammoniter bis nach Aroer*, das Rabba* gegenüber liegt;", footnotes: ["Jaser. Vermutlich Khirbet es-Sar, 10 km westlich vom heutigen Amman.", "Aroer. Stadt an der Grenze zwischen Israel und Ammon.", "Rabba. Hauptstadt der Ammoniter, 38 km östlich vom Jordan, heute: Amman."] },
      { number: 26, text: "von Heschbon bis Ramat-Mizpe* und Betonim*, von Mahanajim* bis an das Gebiet von Debir;", footnotes: ["Ramat-Mizpe. Eventuell 18 km westlich vom heutigen Amman.", "Betonim. 26 km nordöstlich von Jericho", "Mahanajim. Wahrscheinlich 11 km östlich vom Jordan am Jabbok."] },
      { number: 27, text: "in der östlichen Tiefebene des Jordan: Bet-Haram*, Bet-Nimra*, Sukkot und Zafon, also das restliche Gebiet des Reiches von Sihon, der in Heschbon regiert hatte, bis zum Süd-Ende des Sees Kinneret.", footnotes: ["Bet-Haram. 29 km westlich vom heutigen Amman", "Bet-Nimra. Vielleicht identisch mit Nimrim, 8 km östlich des Jordan."] },
      { number: 28, text: "Diese Städte und Dörfer waren den Sippen des Stammes Gad zugeteilt worden." },
      { number: 29, text: "Den Sippen des halben Stammes Manasse hatte Mose das Gebiet zugeteilt," },
      { number: 30, text: "das von Mahanajim an das ganze Reich des Königs Og von Baschan umfasste, dazu alle Zeltdörfer Jaïrs – das waren 60 Ortschaften –," },
      { number: 31, text: "das halbe Gilead, dazu die Städte Aschtarot und Edreï, die zum Königreich Ogs gehört hatten. Dieses Gebiet wurde der Hälfte der Sippen zugeteilt, die von Machir Ben-Manasse abstammten." },
      { number: 32, text: "Die Verteilung des Landes hatte Mose im Steppengebiet von Moab im Ostjordanland gegenüber von Jericho vorgenommen." },
      { number: 33, text: "Aber dem Stamm Levi gab Mose keinen Anteil am Landbesitz. Jahwe, der Gott Israels, sollte selbst ihr Erbbesitz sein und für sie sorgen, wie er es versprochen hatte." },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Es folgt eine Liste mit den Gebieten im Land Kanaan, die der Priester Eleasar und Josua Ben-Nun und die Oberhäupter der einzelnen Stämme an die Israeliten als Erbbesitz austeilten.", heading: "Das Westjordanland" },
      { number: 2, text: "So wie Jahwe es Mose befohlen hatte, wurden sie durchs Los an die neuneinhalb Stämme aufgeteilt." },
      { number: 3, text: "Die anderen zweieinhalb Stämme hatten ihren Erbbesitz ja schon im Ostjordanland von Mose zugeteilt bekommen. Nur den Leviten war kein Land zugeteilt worden." },
      { number: 4, text: "Die Nachkommen Josefs bildeten nämlich zwei Stämme: Manasse und Efraïm. Und die Leviten erhielten keinen Anteil am Land; sie bekamen jedoch Städte, in denen sie wohnen konnten, und Weideplätze für ihr Vieh." },
      { number: 5, text: "Die Israeliten verteilten das Land so, wie Jahwe es Mose befohlen hatte." },
      { number: 6, text: "In Gilgal kamen die Männer des Stammes Juda zu Josua. Und Kaleb Ben-Jefunne aus der Sippe von Kenas sagte zu ihm: \"Du weißt ja, was Jahwe zu Mose, dem Mann Gottes, über mich und dich in Kadesch-Barnea gesagt hat." },
      { number: 7, text: "Ich war damals 40 Jahre alt, als Mose, der Diener Jahwes, mich von Kadesch-Barnea als Kundschafter in dieses Land hier geschickt hatte. Und ich erstattete ihm Bericht, wie ich es in meinem Herzen hatte." },
      { number: 8, text: "Doch meine Brüder, die mit mir gezogen waren, machten dem Volk Angst. Aber ich ließ mich nicht beirren, sondern vertraute auf Jahwe, meinen Gott." },
      { number: 9, text: "An diesem Tag hatte Mose mir unter Eid versprochen: 'Der Teil des Landes, den du als Kundschafter betreten hast, soll dir und deinen Nachkommen für immer gehören! Denn du bist Jahwe, meinem Gott, treu gefolgt.'" },
      { number: 10, text: "Das ist jetzt 45 Jahre her und Jahwe hat mich tatsächlich am Leben erhalten, wie er es mir damals in der Wüste durch Mose versprochen hatte. Heute bin ich 85 Jahre alt" },
      { number: 11, text: "und noch genauso stark wie damals als Kundschafter. Ich kann immer noch kämpfen und in den Krieg ziehen." },
      { number: 12, text: "Gib mir nun dieses Gebirge, von dem Jahwe geredet hat. Du hast damals selbst gehört, dass die Anakiter dort in großen stark befestigten Städten wohnten. Vielleicht steht Jahwe mir bei, dass ich sie vertreiben kann. Er hat es mir ja zugesagt.\"" },
      { number: 13, text: "Da segnete Josua Kaleb und erklärte Hebron zu seinem Erbbesitz." },
      { number: 14, text: "Die Stadt gehört noch heute seinen Nachkommen, weil Kaleb Ben-Jefunne aus der Sippe von Kenas Jahwe, dem Gott Israels, treu gefolgt war." },
      { number: 15, text: "Hebron hieß damals übrigens noch Kirjat-Arba, Stadt des Arba. Das war der größte Mann unter den Anakitern gewesen. Danach war der Krieg zu Ende, und das Land kam zur Ruhe." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Den Sippen des Stammes Juda wurde durch Losentscheid folgendes Gebiet zugewiesen: Im Süden grenzte es an die Wüste Zin, die zu Edom* gehört.", heading: "Der Stamm Juda", footnotes: ["Edom. Land östlich der Araba und südlich vom Toten Meer, bewohnt von den Nachkommen Esaus."] },
      { number: 2, text: "Ihre südliche Grenze begann an der Südspitze des Salzmeeres" },
      { number: 3, text: "und lief in südlicher Richtung am Fuß der Skorpionensteige vorüber nach Zin. Sie führte dann weiter südlich an Kadesch-Barnea vorbei über Hezron hinauf nach Addar, wo sie einen Bogen nach Karka machte." },
      { number: 4, text: "Sie ging weiter durch Azmon und lief am Bach Ägyptens* aus, dem sie bis zum Meer folgte. Das soll eure Südgrenze sein!", footnotes: ["Bach Ägyptens. Heute: Wadi El-Arisch."] },
      { number: 5, text: "Die Ostgrenze bildete das Salzmeer bis zur Einmündung des Jordan. Von dieser Stelle führte die Nordgrenze" },
      { number: 6, text: "nach Bet Hogla hinauf, lief nördlich an Bet-Araba vorbei bis zum Stein Bohans, des Rubeniten." },
      { number: 7, text: "Vom Tal Achor führte sie nach Debir hinauf, wandte sich nordwärts zu den Steinmalen* gegenüber dem Pass von Adummim, der südlich des Baches verläuft. Dann erreichte die Grenze En-Schemesch, die Sonnenquelle, und dann En-Rogel, die Bleicherquelle.", footnotes: ["Steinmale. Wörtlich: Gelilot. Die LXX liest hier Gilgal."] },
      { number: 8, text: "Sie führte durchs Ben-Hinnom-Tal, südlich um den Abhang herum, auf dem die Jebusiterstadt, das heutige Jerusalem, liegt, bis zum Gipfel des Berges, der sich westlich des Hinnom-Tals am Nordrand der Refaïm-Ebene erhebt." },
      { number: 9, text: "Von dort zog sie sich herum auf die Quelle Neftoach zu und lief dann in Richtung der Städte des Berglandes von Efron und weiter nach Baala, dem heutigen Kirjat-Jearim." },
      { number: 10, text: "Von Baala aus ging sie in westliche Richtung zum Gebirge Seïr, lief den Nordhang des Berges Jearim – das ist Kesalon – hinab nach Bet-Schemesch und hinüber nach Timna." },
      { number: 11, text: "Dann verlief sie an der Nordflanke von Ekron in einem Bogen nach Schikkaron hinüber zum Berg Baala und lief bei Jabneel an der Küste des Meeres aus." },
      { number: 12, text: "Das große Meer bildete die Westgrenze. Dies war das Gebiet, das der Stamm Juda mit seinen Sippen erhielt." },
      { number: 13, text: "Nach Befehl Jahwes überließ Josua Kaleb Ben-Jefunne einen Teil des Stammesgebietes von Juda, nämlich Hebron. Damals hieß es noch Kirjat-Arba, die Stadt des Arba, nach dem Stammvater der Anakiter." },
      { number: 14, text: "Kaleb vertrieb die drei Sippen der Anakiter von dort: Scheschai, Ahiman und Talmai." },
      { number: 15, text: "Dann zog er vor die Stadt Debir, die früher noch Kirjat-Sefer hieß." },
      { number: 16, text: "\"Wer Kirjat-Sefer erobert\", versprach er seinen Männern, \"bekommt meine Tochter Achsa zur Frau!\"*", footnotes: ["Achsa zur Frau. Der Sieg im Kampf war eine Möglichkeit, den Brautpreis zu zahlen."] },
      { number: 17, text: "Es war Otniel Ben-Kenas, der Sohn von Kalebs Bruder, der die Stadt einnahm und Achsa zur Frau nehmen durfte." },
      { number: 18, text: "Als sie ihm zugeführt wurde, rang sie ihm die Erlaubnis ab, gleich noch ein Stück Land von ihrem Vater fordern zu dürfen. Dann glitt sie von ihrem Esel, und Kaleb fragte: \"Was hast du?\"" },
      { number: 19, text: "Sie erwiderte: \"Wenn du mich schon in den heißen Negev verheiratet hast, dann gib mir auch ein paar Wasserbecken als Segensgeschenk dazu!\" Da schenkte ihr Kaleb die oberen und die unteren Teichanlagen bei Hebron." },
      { number: 20, text: "Zu dem Land, das dem Stamm Juda und seinen Sippen als Erbbesitz zugeteilt wurde*,", heading: "Die zwölf Bezirke Judas", footnotes: ["zugeteilt wurde. Das Siedlungsgebiet lag hauptsächlich zwischen dem Toten Meer und dem Mittelmeer."] },
      { number: 21, text: "gehörten auch die folgenden Städte:Im Negev an der Grenze von Edom waren es Kabzeel, Eder, Jagur," },
      { number: 22, text: "Kina, Dimona, Adada*,", footnotes: ["Adada. Wahrscheinlich identisch mit Aroer."] },
      { number: 23, text: "Kedesch, Hazor, Jitnan," },
      { number: 24, text: "Sif, Telma, Bealot," },
      { number: 25, text: "Hazor-Haddata, Kirjat-Hezron – das ist Hazor –," },
      { number: 26, text: "Amam, Schema, Molada," },
      { number: 27, text: "Hazar-Gadda, Heschmon, Bet-Pelet," },
      { number: 28, text: "Hazar-Schual, Beerscheba und Bisjotja*.", footnotes: ["Bisjotja. Das meint vielleicht: die dazugehörigen Dörfer."] },
      { number: 29, text: "Baala, Ijim, Ezem," },
      { number: 30, text: "Eltolad, Kesil, Horma," },
      { number: 31, text: "Ziklag, Mandmanna, Sansanna," },
      { number: 32, text: "Lebaot, Schilhim, Ajin und Rimmon. Das sind 29 Städte* mit Dörfern.", footnotes: ["29 Städte. Die Zahl der genannten Ortschaften ist höher. Vielleicht waren einige der genannten Ortschaften wichtige Dörfer, siehe Hazor V. 23 mit V. 25."] },
      { number: 33, text: "In der Schefela Eschtaol, Zora, Aschna," },
      { number: 34, text: "Sanoach, En-Gannim, Tappuach, Enam," },
      { number: 35, text: "Jarmut, Addulam, Socho, Aseka," },
      { number: 36, text: "Schaarajim, Aditajim, Gedera und Gederotajim – 14 Städte mit ihren Dörfern." },
      { number: 37, text: "Außerdem: Zenan, Hadascha, Migdal-Gad," },
      { number: 38, text: "Dilan, Mizpe, Jokteel," },
      { number: 39, text: "Lachisch, Bozkat, Eglon," },
      { number: 40, text: "Kabbon, Lachmas, Kitlisch," },
      { number: 41, text: "Gederot, Bet-Dagon, Naama und Makkeda – 16 Städte mit ihren Dörfern." },
      { number: 42, text: "Weiter: Libna, Eter, Aschan," },
      { number: 43, text: "Jiftach, Aschna, Nezib," },
      { number: 44, text: "Keïla, Achsib und Marescha – neun Städte mit ihren Dörfern." },
      { number: 45, text: "Dann: Ekron mit seinen Tochterstädten und Dörfern" },
      { number: 46, text: "und die Ortschaften westlich davon, die auf der Seite von Aschdod liegen," },
      { number: 47, text: "dann Aschdod mit seinen Tochterstädten und Dörfern, Gaza mit seinen Tochterstädten und Dörfern bis zum großen Meer und nach Süden bis zum Bach Ägyptens." },
      { number: 48, text: "Im Gebirge: Schamir, Jattir, Socho," },
      { number: 49, text: "Danna, Kirjat-Sefer – das heutige Debir –," },
      { number: 50, text: "Anab, Eschtemoa, Anim," },
      { number: 51, text: "Goschen, Holon, Gilo – elf Städte mit ihren Dörfern." },
      { number: 52, text: "Außerdem: Arab, Duma, Eschan," },
      { number: 53, text: "Janum, Bet-Tappuach, Afeka," },
      { number: 54, text: "Humta, Kirjat-Arba – das heutige Hebron – und Zior: neun Städte mit ihren Dörfern." },
      { number: 55, text: "Dann: Maon, Karmel, Sif, Jutta," },
      { number: 56, text: "Jesreel, Jokdeam, Sanoach," },
      { number: 57, text: "Kain, Gibea, und Timna – zehn Städte mit ihren Dörfern." },
      { number: 58, text: "Weiter: Halhul, Bet-Zur, Gedor," },
      { number: 59, text: "Maarat, Bet-Anot und Eltekon – sechs Städte mit ihren Dörfern.Außerdem: Tekoa, Efrata – das ist Bethlehem –, Peor, Etam, Kulon, Tatam, Schoresch, Kerem, Gallim, Bet-Ter und Manocho – elf Städte mit ihren Dörfern.*", footnotes: ["Dörfern. Der Text ab Tekoa ist nur in der LXX überliefert."] },
      { number: 60, text: "Weiter: Kirjat-Baal – das ist Kirjat-Jearim – und Rabba – zwei Städte mit ihren Dörfern." },
      { number: 61, text: "In der Wüste: Bet-Araba, Middin, Sechacha," },
      { number: 62, text: "Nibschan und Ir-Melach, die Salzstadt, und En-Gedi – sechs Städte mit ihren Dörfern." },
      { number: 63, text: "Nur die Jebusiter, die in Jerusalem wohnten, konnten die Männer des Stammes Juda nicht vertreiben. Bis heute wohnen sie mit den Judäern zusammen." },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Für die Nachkommen Josefs bestimmte das Los folgendes Gebiet: Die Grenze begann am Jordan auf der Höhe von Jericho und lief an den Quellen östlich der Stadt vorbei durch die Wüste, die sich ins Gebirge hinaufzieht bis nach Bet-El.", heading: "Die Josefstämme" },
      { number: 2, text: "Von dort lief sie weiter nach Lus* und zog sich zum Gebiet der Arkiter* hinüber nach Atarot*,", footnotes: ["Lus. Kanaanitischer Ort nahe bei Bet-El.", "Arkiter. Sippe aus den Nachkommen Kanaans.", "Atarot. Die Lage des Ortes ist unbekannt."] },
      { number: 3, text: "zog sich bergab nach Westen zum Gebiet der Jafletiter* und zum unteren Bet-Horon über Geser bis zum Meer.", footnotes: ["Jafletiter. Vielleicht die Nachkommen von Jaflet 1. Chronik 7,32."] },
      { number: 4, text: "Das war die Südgrenze des Gebiets, das die Nachkommen Josefs, die Stämme Efraïm und Manasse, erhielten." },
      { number: 5, text: "Der Stamm Efraïm erhielt folgendes Gebiet: Seine Südgrenze begann östlich von Atarot-Addar, lief durch das obere Bet-Horon", heading: "Der Stamm Efraïm" },
      { number: 6, text: "und von dort zum Meer. Die Nordgrenze ging von Michmetat ostwärts nach Taanat-Schilo bis nach Janoach." },
      { number: 7, text: "Von Janoach stieg sie hinunter nach Atarot und Naara, stieß auf Jericho und lief am Jordan aus." },
      { number: 8, text: "Von Tappuach aus lief die Grenze westwärts zum Bach Kana und endete am Meer. Das ist der Erbbesitz für den Stamm Efraïm mit seinen Sippen." },
      { number: 9, text: "Dazu kamen noch die Städte und Dörfer, die den Efraïmiten zugesprochen wurden, obwohl sie im Stammesgebiet von Manasse lagen." },
      { number: 10, text: "Doch sie vertrieben die Kanaaniter von Geser nicht. So kam es, dass diese bis heute dort wohnen, aber Zwangsarbeiten verrichten müssen." },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Ein Teil der Nachkommen von Manasse, dem ältesten Sohn Josefs, hatte Gilead und Baschan erhalten. Das waren die Nachkommen von Manasses ältestem Sohn Machir und dessen Sohn Gilead, einem kampferprobten Mann.", heading: "Der halbe Stamm Manasse" },
      { number: 2, text: "Auch den anderen Söhnen Manasses und ihren Sippen wurden Gebiete zugewiesen: den Nachkommen von Abiëser, Helek, Asriël, Schechem, Hefer und Schemida." },
      { number: 3, text: "Doch Zelofhad, der Sohn Hefers und Enkel Gileads aus der Sippe von Machir Ben-Manasse, hatte keine Söhne, sondern nur Töchter. Sie hießen Machla, Noa, Hogla, Milka und Tirza." },
      { number: 4, text: "Diese Frauen gingen zum Priester Eleasar und zu Josua Ben-Nun und den Stammesoberhäuptern und sagten: \"Jahwe hat Mose angewiesen, uns einen Erbbesitz unter unseren Brüdern zu geben.\" Da gab er ihnen nach der Anweisung Jahwes einen Erbbesitz unter der Sippe ihres Vaters." },
      { number: 5, text: "So kam es, dass der Stamm Manasse außer dem Land Gilead und Baschan auch westlich des Jordan zehn Anteile besaß," },
      { number: 6, text: "denn die Sippen der weiblichen Nachkommen Manasses erhielten dort ebenso einen Anteil wie die der männlichen. Das Land Gilead wurde aber nur unter die männlichen Nachkommen aufgeteilt." },
      { number: 7, text: "Das Gebiet Manasses grenzte im Norden an das des Stammes Ascher. Die Südgrenze verlief von Michmetat gegenüber von Sichem zum Siedlungsgebiet von En-Tappuach." },
      { number: 8, text: "Die Umgebung von Tappuach gehörte Manasse, Tappuach selbst gehörte zu Efraïm." },
      { number: 9, text: "Die Grenze verlief dann südlich vom Kana-Bach bis zum Meer. Nördlich des Baches begann das Gebiet Manasses. Im Westen reichte es bis ans Meer. Die Städte südlich des Baches gehören zu Efraïm, obwohl sie noch im Stammesgebiet von Manasse lagen." },
      { number: 10, text: "Das Bachtal bildete also die Grenze zwischen den beiden Stämmen. Das Meer war für beide die Westgrenze. Im Norden stieß das Land Manasses an das Gebiet des Stammes Ascher und im Osten an das von Issachar." },
      { number: 11, text: "Und in den Stammesgebieten von Issachar und Ascher gehörten einige Städte mit den umliegenden Dörfern zu Manasse: Bet-Schean, Jibleam, der ganze Bezirk von Dor, En-Dor, Taanach und Megiddo, das Dreihügelgebiet." },
      { number: 12, text: "Die Männer von Manasse konnten diese Städte allerdings nicht erobern. So gelang es den Kanaanitern, in diesem Gebiet wohnen zu bleiben." },
      { number: 13, text: "Auch als die Israeliten stärker wurden, vertrieben sie die Kanaaniter nicht, verpflichteten sie aber zu Zwangsarbeiten." },
      { number: 14, text: "Da beschwerten sich die Nachkommen Josefs bei Josua: \"Warum hast du uns bei der Landverteilung nur den Anteil für einen einzigen Stamm gegeben? Wir sind doch so viele Leute. Jahwe hat uns reich gesegnet und zu einem großen Volk gemacht.\"" },
      { number: 15, text: "Da sagte Josua: \"Wenn ihr so viele seid und euch das Gebirge Efraïm nicht ausreicht, dann zieht doch in das Waldgebiet der Perisiter und Refaïter und rodet euch dort Land.\"" },
      { number: 16, text: "Da sagten die Nachkommen Josefs: \"Das Gebirge ist zu klein für uns, und die Kanaaniter in der Ebene Jesreel bis nach Bet-Schean haben eiserne Streitwagen.\"" },
      { number: 17, text: "Da erwiderte Josua den Nachkommen Josefs, den Stämmen Efraïm und Manasse: \"Ja, ihr seid ein großes und starkes Volk und sollt nicht nur einen Losanteil haben." },
      { number: 18, text: "Ihr bekommt ein bewaldetes Bergland mit seinen Ausläufern dazu. Den Wald könnt ihr roden, und die Kanaaniter werdet ihr vertreiben, auch wenn sie stark sind und eiserne Streitwagen haben.\"" },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Die ganze Gemeinschaft Israels versammelte sich in Schilo* und richtete dort das Zelt der Begegnung mit Gott auf. Das Land war jetzt erobert.", heading: "Das noch nicht eroberte Gebiet (18-21)\nDie Aufteilung des restlichen Landes", footnotes: ["Schilo. Religiöses Zentrum im Hügelland von Efraïm, 32 km nördlich von Jerusalem."] },
      { number: 2, text: "Allerdings hatten sieben Stämme ihr Land noch nicht in Besitz genommen." },
      { number: 3, text: "Da sagte Josua zu den Israeliten: \"Wie lange wollt ihr noch warten, bis ihr das Land, das Jahwe, der Gott eurer Väter, euch gegeben hat, nun auch in Besitz nehmt?" },
      { number: 4, text: "Wählt drei Männer aus jedem Stamm aus, die ich durchs Land schicken kann. Sie sollen die Gebiete erfassen, in denen sie wohnen wollen, und dann zu mir zurückkommen." },
      { number: 5, text: "Das ganze Land sollen sie in sieben Gebiete aufteilen, wobei sie die Wohngebiete von Juda im Süden und den Josefstämmen im Norden aussparen." },
      { number: 6, text: "So sollt ihr die sieben Teile schriftlich aufnehmen und mir die Liste herbringen. Dann werde ich sie hier vor Jahwe, unserem Gott, für euch auslosen." },
      { number: 7, text: "Nur die Leviten bekommen kein eigenes Land unter euch, denn ihr Erbbesitz ist das Priestertum für Jahwe. Auch die Stämme Gad, Ruben und halb Manasse bekommen nichts mehr zugeteilt, denn sie haben ihren Erbbesitz schon im Ostjordanland von Mose, dem Diener Jahwes, erhalten.\"" },
      { number: 8, text: "Da machten sich die Männer auf den Weg. Josua hatte ihnen befohlen: \"Zieht durch das ganze Land und nehmt es schriftlich auf! Wenn ihr fertig seid, bringt ihr eure Verzeichnisse zu mir! Ich werde dann hier vor Jahwe in Schilo die Gebiete für euch auslosen.\"" },
      { number: 9, text: "Die Männer durchzogen also das ganze Land und fertigten eine Liste aller Städte an, die in jedem der sieben Teile lagen. Dann kehrten sie ins Lager bei Schilo zurück und überreichten die entstandene Schriftrolle Josua." },
      { number: 10, text: "Dieser ließ Jahwe durch das Los entscheiden und teilte den restlichen Stämmen Israels das Land zu." },
      { number: 11, text: "Das Los für den Stamm Benjamin und seine Sippen fiel auf das Gebiet zwischen dem Stamm Juda und den Josefstämmen*.", heading: "Der Stamm Benjamin", footnotes: ["zwischen ... Josefstämmen. Ein relativ kleines, aber strategisch wichtiges Gebiet zwischen den mächtigen Stämmen Juda und Efraïm."] },
      { number: 12, text: "Seine Nordgrenze begann am Jordan und stieg dann nördlich von Jericho auf das Gebirge nach Westen zu und endete im Weidegebiet von Bet-Awen." },
      { number: 13, text: "Dann zog sie sich hinüber nach Lus, dem heutigen Bet-El, lief südlich der Stadt über den Höhenzug bis nach Atrot-Addar hinunter zu dem Berg, der südlich vom unteren Bet-Horon liegt." },
      { number: 14, text: "Von seiner Westseite aus wandte sie sich nach Süden und lief bis nach Kirjat-Baal, dem heutigen Kirjat-Jearim, das zu Juda gehört. Das war seine Westgrenze." },
      { number: 15, text: "Die Südgrenze begann am westlichen Ende von Kirjat-Jearim und führte ostwärts zur Quelle Neftoach," },
      { number: 16, text: "dann senkte sie sich zum Fuß des Berges an der Nordseite der Ebene Refaïm, hinter dem das Hinnom-Tal beginnt, und führte dann durch das Hinnom-Tal am Südabhang der Jebusiterstadt entlang zur Bleicherquelle En-Rogel." },
      { number: 17, text: "Von dort lief sie nordwärts zur Sonnenquelle En-Schemesch und weiter zu den Bezirken, die der Adummim-Steige gegenüber liegen, bis hinab zum Stein Bohans, des Rubeniten." },
      { number: 18, text: "Sie ging nördlich am Bergrücken von Bet-Araba vorbei und führte dann weiter in die Araba hinunter." },
      { number: 19, text: "Dann lief die Grenze nördlich am Bergrücken von Bet-Hogla vorbei und endete an der Einmündung des Jordan in das Salzmeer." },
      { number: 20, text: "Die Ostgrenze des Gebietes, das den Sippen des Stammes Benjamin zugeteilt wurde, bildete der Jordan." },
      { number: 21, text: "Dem Stamm und seinen Sippen gehörten folgende Städte: Jericho, Bet-Hogla, Emek-Keziz," },
      { number: 22, text: "Bet-Araba, Zemarajim, Bet-El," },
      { number: 23, text: "Awim, Para, Ofra," },
      { number: 24, text: "Kefar-Ammoni, Ofni und Geba. Das waren zwölf Städte mit ihren Dörfern." },
      { number: 25, text: "Dazu kamen noch Gibeon, Rama, Beerot," },
      { number: 26, text: "Mizpe, Kefira, Moza," },
      { number: 27, text: "Rekem, Jirpeel, Tarala," },
      { number: 28, text: "Zela, Elef, die Jebusiterstadt, das heutige Jerusalem, Gibea und Kirjat. Das sind 14 Städte mit ihren Dörfern. Das war der Erbbesitz der Sippen des Stammes Benjamin." },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Das zweite Los fiel auf den Stamm Simeon mit seinen Sippen. Sein Erbbesitz befand sich mitten im Stammesgebiet von Juda.*", heading: "Der Stamm Simeon", footnotes: ["Simeon ... Juda. Simeon siedelte überwiegend im westlichen Negev, zwischen Beerscheba und dem Mittelmeer."] },
      { number: 2, text: "Ihm gehörten die Städte Beerscheba oder Scheba*, Molada", footnotes: ["Scheba. Möglicherweise handelt es sich um die gleiche Stadt, weil die Liste nur 13 Städte zählt."] },
      { number: 3, text: "Hazar-Schual, Baala, Ezem," },
      { number: 4, text: "Eltolad, Betul, Horma," },
      { number: 5, text: "Ziklag, Bet-Markabot, Hazar-Susa," },
      { number: 6, text: "Bet-Lebaot und Scharuhen. Das waren 13 Städte mit ihren Dörfern." },
      { number: 7, text: "Dazu kamen noch weitere vier Städte mit ihren Dörfern: Ajin, Rimmon, Eter und Aschan" },
      { number: 8, text: "und die Dörfer, die in dem ganzen Gebiet um diese Städte herum bis nach Baalat-Beer und Ramat-Negev liegen. Das war der Erbbesitz der Sippen des Stammes Simeon." },
      { number: 9, text: "Sein Anteil wurde also vom Land des Stammes Juda genommen, weil Judas Anteil zu groß für ihn allein war. Deswegen lag das Gebiet Simeons mitten in Juda." },
      { number: 10, text: "Das dritte Los fiel auf den Stamm Sebulon* mit seinen Sippen. Sein Gebiet reichte bis nach Sarid.", heading: "Der Stamm Sebulon", footnotes: ["Sebulon. Sein Stammesgebiet lag in der südlichen Mitte Galiläas, also nördlich der Jesreel-Ebene, wobei einige Städte wohl auch in der Ebene selbst lagen."] },
      { number: 11, text: "Von dort aus stieg die Grenze westwärts nach Marala, stieß an Dabbeschet und folgte dem Bach, der vor Jokneam fließt." },
      { number: 12, text: "Nach Osten zu lief die Grenze von Sarid am Gebiet von Kislot-Tabor vorbei nach Daberat und hinauf nach Jafia." },
      { number: 13, text: "Von dort aus führte sie nach Osten über Gat-Hefer, Et-Kazin und Rimmon bis nach Nea." },
      { number: 14, text: "Von dort verlief die Nordgrenze über Hannaton zum Tal von Jiftach-El." },
      { number: 15, text: "Außerdem gehören noch die Städte Kattat, Nahalal, Schimron, Jidala und Bethlehem* dazu. Das waren insgesamt zwölf Städte mit ihren Dörfern.", footnotes: ["Bethlehem. Gemeint ist Bethlehem in Sebulon, 11 km westlich von Nazaret."] },
      { number: 16, text: "Diese Städte und Dörfer waren der Erbbesitz der Sippen des Stammes Sebulon." },
      { number: 17, text: "Das vierte Los fiel auf den Stamm Issachar* mit seinen Sippen.", heading: "Der Stamm Issachar", footnotes: ["Issachar siedelte im östlichen Jesreel-Tal und im östlichen Niedergaliläa."] },
      { number: 18, text: "Sein Gebiet umfasste folgende Städte: Jesreel, Kesulot, Schunem," },
      { number: 19, text: "Hafarajim, Schion, Anaharat," },
      { number: 20, text: "Daberat, Kischjon, Ebez," },
      { number: 21, text: "Remet, En-Gannim, En-Hadda und Bet-Pazzez." },
      { number: 22, text: "Die Grenze führte über Tabor*, Schahazajim, Bet-Schemesch und endete am Jordan. Das waren 16 Städte mit ihren Dörfern.", footnotes: ["Tabor. Hier ist wahrscheinlich ein Ort namens Tabor gemeint, nicht der Berg."] },
      { number: 23, text: "Diese Städte und Dörfer waren der Erbbesitz der Sippen des Stammes Issachar." },
      { number: 24, text: "Das fünfte Los fiel auf den Stamm Ascher mit seinen Sippen.", heading: "Der Stamm Ascher" },
      { number: 25, text: "Sein Gebiet* umfasste die Städte Helkat, Hali, Beten, Achschaf,", footnotes: ["Sein Gebiet. Das war die nordwestliche Ecke Israels. In Aschers Gebiet lag der einzige natürliche Hafen Israels: Akko. Erst unter David und Salomo kam das Gebiet ganz unter die Herrschaft Israels."] },
      { number: 26, text: "Alammelech, Amat und Mischal. Seine Grenze führte um das Karmelgebirge bis zum Fluss Libnat." },
      { number: 27, text: "Dort wandte sie sich ostwärts nach Bet-Dagon, erreichte das Gebiet Sebulons und folgte dessen Grenze bis zum Tal Jiftach-El im Norden. Sie lief links weiter nach Kabul," },
      { number: 28, text: "Abdon, Rehob, Hammon und Kana bis zum Gebiet der großen Stadt Sidon." },
      { number: 29, text: "Dort bog die Grenze nach Rama ab und erreichte die befestigte Stadt Tyrus. Hier machte sie einen Bogen in Richtung Hosa und endete am Meer. Auch die Städte Mahaleb, Achsib," },
      { number: 30, text: "Umma, Afek und Rehob gehörten dazu. Das waren 22 Städte mit ihren Dörfern." },
      { number: 31, text: "Diese Städte und Dörfer waren der Erbbesitz der Sippen des Stammes Ascher." },
      { number: 32, text: "Das sechste Los fiel auf den Stamm Naftali* mit seinen Sippen.", heading: "Der Stamm Naftali", footnotes: ["Naftali besiedelte östlich von Ascher das Hügelland von Galiläa. Seine Ostgrenze verlief vom See Gennesaret bis zu den Quellen des Jordan."] },
      { number: 33, text: "Seine Grenze ging von Helef aus ostwärts nach der Terebinthe* bei Zaanajim über den Adami-Pass und Jabneel bis Lakkum und endete am Jordan.", footnotes: ["Terebinthe. Belaubter Baum mit breitem Wipfel, der nicht mehr als 7 m hoch wird und als Schattenspender geschätzt ist."] },
      { number: 34, text: "In westlicher Richtung führte die Grenze über Asnot-Tabor nach Hukkok. Im Süden grenzte das Gebiet Naftalis an Sebulon, im Westen an Ascher und am Jordan an das Land, das von Juda erobert* worden war.", footnotes: ["von Juda erobert. Wörtlich: das Land Juda. Gemeint ist vielleicht das Land, das von der Sippe des Judäers Jaïr erobert worden war, jetzt allerdings im Gebiet Manasses lag, siehe 1. Chronik 2,22."] },
      { number: 35, text: "Die befestigten Städte in diesem Gebiet waren Ziddim, Zer, Hammat, Rakkat, Kinneret," },
      { number: 36, text: "Adama, Rama, Hazor," },
      { number: 37, text: "Kedesch, Edreï, En-Hazor," },
      { number: 38, text: "Jiron, Migdal-El, Horem, Bet-Anat und Bet-Schemesch. Das waren 19 Städte mit ihren Dörfern." },
      { number: 39, text: "Diese Städte und Dörfer waren der Erbbesitz der Sippen des Stammes Naftali." },
      { number: 40, text: "Das siebte Los fiel auf den Stamm Dan mit seinen Sippen.", heading: "Der Stamm Dan" },
      { number: 41, text: "Zu seinem Gebiet* gehörten die Städte Zora, Eschtaol, Ir-Schemesch,", footnotes: ["Gebiet. Das war westlich des Stammes Benjamin."] },
      { number: 42, text: "Schaalbim, Ajalon, Jitla," },
      { number: 43, text: "Elon, Timna, Ekron," },
      { number: 44, text: "Elteke, Gibbeton, Baalat," },
      { number: 45, text: "Jehud, Bene-Berak, Gat-Rimmon," },
      { number: 46, text: "Me-Jarkon mit dem Gebiet gegenüber von Jafo." },
      { number: 47, text: "Aber dieses Gebiet ging ihnen verloren.* So zogen die Daniten nach Norden gegen Leschem*. Sie eroberten die Stadt, erschlugen deren Bewohner mit dem Schwert und nahmen sie in Besitz. Dann benannten sie Leschem in Dan um – nach dem Namen ihres Stammvaters.", footnotes: ["Gebiet ... verloren. Siehe Richter 1,34.", "Leschem. Das ist Lajisch, siehe Richter 18,29."] },
      { number: 48, text: "Diese Städte und Dörfer waren der Erbbesitz der Sippen des Stammes Dan." },
      { number: 49, text: "Als das ganze Land verteilt war, gaben die Israeliten auch Josua Ben-Nun einen Erbbesitz in ihrer Mitte.", heading: "Josuas Erbe" },
      { number: 50, text: "Auf Anweisung Jahwes gaben sie ihm die Stadt, die er wollte. Es war Timnat-Serach* im Gebirge Efraïm. Er baute die Stadt aus und ließ sich dort nieder.", footnotes: ["Timnat-Serach. 29 km nordwestlich von Jerusalem"] },
      { number: 51, text: "Das sind die erblichen Anteile, die der Priester Eleasar und Josua Ben-Nun zusammen mit den Stammesoberhäuptern den Israeliten durch Losentscheid zuwiesen. Das geschah in der Gegenwart Jahwes in Schilo vor dem Eingang vom Zelt der Gottesbegegnung. So wurde die Verteilung des Landes abgeschlossen." },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Jahwe sagte zu Josua:", heading: "Die Asylstädte" },
      { number: 2, text: "\"Bestimmt jetzt die Asylstädte, von denen ich durch Mose zu euch gesprochen habe." },
      { number: 3, text: "Sie sollen demjenigen Schutz bieten, der aus Versehen, ohne Vorsatz, einen Menschen getötet hat. An diesen Orten ist er vor dem Bluträcher* sicher.", footnotes: ["Der Bluträcher war ein Verwandter des Getöteten. Diese Regelung verhinderte ein endloses Blutvergießen durch die jeweiligen Familienmitglieder."] },
      { number: 4, text: "Er soll in eine dieser Städte fliehen und sich am Stadttor dem Ältestenrat stellen und seinen Fall schildern. Dann soll er in die Stadt aufgenommen werden und eine Unterkunft erhalten." },
      { number: 5, text: "Wenn er von einem Bluträcher verfolgt wird, darf er nicht ausgeliefert werden, denn er hat die Tat nicht vorsätzlich, sondern aus Versehen begangen." },
      { number: 6, text: "Wenn seine Angaben vom Gericht der Gemeinschaft bestätigt wurden, soll er bis zum Tod des Hohen Priesters in dieser Stadt bleiben. Dann kann er in seine Heimatstadt, aus der er geflohen ist, zurückkehren.\"" },
      { number: 7, text: "Sie bestimmten dazu Kedesch in Galiläa auf dem Gebirge Naftali, außerdem Sichem auf dem Gebirge Efraïm und Kirjat-Arba, das heutige Hebron, auf dem Gebirge Juda." },
      { number: 8, text: "Im Ostjordanland bestimmten sie Bezer, das in der Wüste östlich von Jericho liegt und zum Stamm Ruben gehört, außerdem Ramot in Gilead, das zum Stamm Gad gehört, und Golan in Baschan, das zum Stamm Manasse gehört." },
      { number: 9, text: "Das waren die Städte, die den Israeliten und den Fremden, die unter ihnen lebten, als Zufluchtsorte dienten. Jeder, der unabsichtlich einen Menschen getötet hatte, konnte dorthin fliehen, damit er nicht vom Bluträcher getötet wurde, bevor er vor dem Gericht der Gemeinschaft gestanden hatte." },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Dann kamen die Sippenoberhäupter des Stammes Levi zum Priester Eleasar, zu Josua Ben-Nun und den Oberhäuptern der Stämme Israels.", heading: "Die Levitenstädte" },
      { number: 2, text: "Das war in Schilo im Land Kanaan. Sie sagten: \"Jahwe hat durch Mose befohlen, dass wir Städte bekommen sollen, in denen wir wohnen können und wo wir Weideland für unser Vieh haben.\"" },
      { number: 3, text: "Da traten ihnen die Israeliten von ihrem Erbbesitz bestimmte Städte mit ihrem Weideland ab." },
      { number: 4, text: "Als das Los für die Sippen der Kehatiter fiel, erhielten die Nachkommen Aarons unter den Leviten von den Stämmen Juda, Simeon und Benjamin durch das Los 13 Städte." },
      { number: 5, text: "Die übrigen Nachkommen Kehats erhielten von den Stämmen Efraïm, Dan und dem halben Stamm Manasse durch das Los zehn Städte." },
      { number: 6, text: "Die Sippe Gerschon bekam 13 Städte von den Sippen der Stämme Issachar, Ascher, Naftali und Ost-Manasse in Baschan." },
      { number: 7, text: "Die Sippe Merari erhielt von den Stämmen Ruben, Gad und Sebulon zwölf Städte." },
      { number: 8, text: "Diese Städte mit ihrem Weideland teilten die Israeliten den Leviten zu, wie Jahwe es durch Mose angeordnet hatte und es das Los nun bestimmte." },
      { number: 9, text: "Die Stämme Juda und Simeon gaben folgende namentlich aufgezählte Städte" },
      { number: 10, text: "an die Nachkommen Aarons, die Leviten aus der Sippe Kehat, ab, denn diese bekamen das erste Los." },
      { number: 11, text: "Sie erhielten die Stadt des Arba, des Stammvaters der Anakiter, das heutige Hebron, im Gebirge Juda samt seinen Weideplätzen." },
      { number: 12, text: "Das Ackerland der Stadt und die Dörfer der Umgebung hatten die Israeliten ja schon Kaleb Ben-Jefunne als Erbbesitz gegeben." },
      { number: 13, text: "Gleichzeitig diente Hebron als Asylstadt für Totschläger. Die Nachkommen des Priesters Aaron erhielten also folgende Städte mit ihren Weideplätzen: Hebron, Libna," },
      { number: 14, text: "Jattir, Eschtemoa," },
      { number: 15, text: "Holon, Debir," },
      { number: 16, text: "Ajin, Jutta, Bet-Schemesch. Das waren neun Städte von diesen beiden Stämmen." },
      { number: 17, text: "Dazu vom Stamm Benjamin: Gibeon, Geba," },
      { number: 18, text: "Anatot, und Almon – vier Städte." },
      { number: 19, text: "Damit besaß das Priestergeschlecht Aarons 13 Städte mit Weideland." },
      { number: 20, text: "Die übrigen Familien der Sippe Kehat aus dem Stamm Levi erhielten einige Städte aus dem Stamm Efraïm durch Los zugesprochen:" },
      { number: 21, text: "Sichem* auf dem Gebirge Efraïm, das zugleich Asylstadt für Totschläger war, Geser,", footnotes: ["Sichem. 48 km nördlich von Jerusalem."] },
      { number: 22, text: "Kibzajim und Bet-Horon – vier Städte." },
      { number: 23, text: "Vom Stamm Dan erhielten sie Elteke, Gibbeton," },
      { number: 24, text: "Ajalon und Gat-Rimmon – vier Städte." },
      { number: 25, text: "Und von West-Manasse erhielten sie zwei Städte: Taanach und Gat-Rimmon*.", footnotes: ["Gad-Rimmon. Wahrscheinlich ist Jibleam nach der Parallele in 1. Chronik 6,55 gemeint."] },
      { number: 26, text: "Das waren insgesamt zehn Städte mit Weideland für die restlichen Familien der Sippe Kehat." },
      { number: 27, text: "Die Nachkommen Gerschons aus dem Stamm Levi erhielten zwei Städte mit Weideplätzen in Ost-Manasse: Golan, die Asylstadt für Totschläger in Baschan, und Beëschtera*.", footnotes: ["Beëschtera. Vermutlich ein anderer Name für Aschtarot."] },
      { number: 28, text: "Vom Stamm Issachar bekamen sie Kischjon, Daberat," },
      { number: 29, text: "Jarmut und En-Gannim – vier Städte." },
      { number: 30, text: "Vom Stamm Ascher: Mischal, Abdon," },
      { number: 31, text: "Helkat und Rehob – vier Städte." },
      { number: 32, text: "Vom Stamm Naftali: Kedesch in Galiläa, die Asylstadt für Totschläger, Hammot-Dor und Kartan – drei Städte." },
      { number: 33, text: "Das waren insgesamt 13 Städte mit Weideland für die Familien der Sippe Gerschon." },
      { number: 34, text: "Die Nachkommen Meraris, zu denen alle übrigen Leviten gehörten, erhielten vom Stamm Sebulon Jokneam, Karta," },
      { number: 35, text: "Dimna* und Nahalal – vier Städte.", footnotes: ["Dimna. Anderer Name für Rimmon, siehe Josua 19,13; 1. Chronik 6,62."] },
      { number: 36, text: "Vom Stamm Ruben: Bezer, Jahaz," },
      { number: 37, text: "Kedemot und Mefaat – vier Städte." },
      { number: 38, text: "Vom Stamm Gad: Ramot in Gilead, die Asylstadt für Totschläger, Mahanajim," },
      { number: 39, text: "Heschbon und Jaser – vier Städte." },
      { number: 40, text: "Das Los der Sippe Merari aus dem Stamm Levi umfasste insgesamt zwölf Städte mit Weideland." },
      { number: 41, text: "Alle Leviten erhielten zusammen 48 Städte im Stammesgebiet Israels mit Weideland." },
      { number: 42, text: "Jede dieser Städte war von Weideland umgeben." },
      { number: 43, text: "So gab Jahwe den Israeliten das ganze Land, das er ihren Vorfahren unter Eid versprochen hatte. Sie nahmen es in Besitz und siedelten sich darin an." },
      { number: 44, text: "Außerdem verschaffte ihnen Jahwe an allen Grenzen Ruhe, wie er es ihren Vorfahren unter Eid zugesagt hatte. Kein Feind konnte vor ihnen bestehen. Er gab sie alle in ihre Gewalt." },
      { number: 45, text: "So hatte Jahwe alle seine Zusagen erfüllt, keines seiner Versprechen an Israel war ausgeblieben. Alles traf ein." },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Damals rief Josua die Männer von Ruben, Gad und Ost-Manasse zusammen", heading: "22-24: Josuas Abschied und Tod\nRuhe für das ganze Land" },
      { number: 2, text: "und sagte zu ihnen: \"Ihr habt alles getan, was Mose, der Diener Jahwes, euch befohlen hat. Auch mir seid ihr immer gehorsam gewesen." },
      { number: 3, text: "Ihr habt eure Bruderstämme bis heute nie im Stich gelassen und habt den Auftrag Jahwes, eures Gottes, während dieser ganzen langen Zeit treu ausgeführt." },
      { number: 4, text: "Jetzt hat Jahwe euren Brüdern Ruhe verschafft, wie er es ihnen versprochen hatte. Kehrt nun in euer eigenes Land auf der anderen Seite des Jordan zurück, das Mose, der Diener Jahwes, euch gegeben hat." },
      { number: 5, text: "Doch vergesst nie, was euch Mose im Auftrag Jahwes eingeschärft hat: Ihr sollt Jahwe, euren Gott, lieben und auf seinen Wegen gehen. Ihr sollt euch an seine Gebote halten, ihm treu sein und ihm mit ganzem Herzen und allen Kräften dienen!\"" },
      { number: 6, text: "Dann segnete Josua sie und ließ sie nach Hause ziehen." },
      { number: 7, text: "Der einen Hälfte des Stammes Manasse hatte schon Mose das Land östlich des Jordan in Baschan gegeben. Der anderen Hälfte hatte nun Josua ihr Land bei ihren Brüdern westlich des Jordan zugewiesen. Als Josua die Männer von Ost-Manasse entließ," },
      { number: 8, text: "sagte er ihnen: \"Ihr kommt mit reichen Schätzen nach Hause, mit großen Viehherden, mit einer Menge Silber, Gold, Bronze, Eisen und Kleidung. Teilt diese Kriegsbeute mit euren Stammesbrüdern.\"" },
      { number: 9, text: "So verließen die Männer der Stämme Ruben, Gad und Ost-Manasse die übrigen Israeliten in Schilo, das in Kanaan liegt, und zogen in Richtung des Landes Gilead, wo sie sich aufgrund der Zusage Jahwes durch Mose angesiedelt hatten.", heading: "Der Altar am Jordan" },
      { number: 10, text: "Als sie zu den Steinmalen* des Jordan kamen, die noch in Kanaan liegen, bauten die Männer von Ruben, Gad und Ost-Manasse dort einen großen Altar.", footnotes: ["Steinmale. Wörtlich: Gelilot. Die Bezeichnung ist nicht eindeutig, vielleicht: Steinkreis oder zusammengerollte Steine."] },
      { number: 11, text: "Als die Israeliten die Nachricht erhielten: \"Die Stämme Ruben, Gad und Ost-Manasse haben bei den Steinmalen im Jordantal einen Altar vor das Land Kanaan gebaut, der noch auf unserer Seite steht\"," },
      { number: 12, text: "versammelten sich alle Männer Israels in Schilo, um gegen die Oststämme Krieg zu führen." },
      { number: 13, text: "Sie schickten Pinhas, den Sohn des Priesters Eleasar, nach Gilead zu den Stämmen Ruben, Gad und Ost-Manasse." },
      { number: 14, text: "Er wurde von zehn Männern aus den Stämmen Israels begleitet. Jeder von ihnen war das Oberhaupt einer ganzen Sippe in den Heereseinheiten Israels." },
      { number: 15, text: "In Gilead angekommen stellten sie die Oststämme zur Rede und fragten sie" },
      { number: 16, text: "im Namen der ganzen Gemeinde Jahwes: \"Warum habt ihr dem Gott Israels die Treue gebrochen? Warum wendet ihr euch von Jahwe ab und baut euch einen Altar? Damit habt ihr euch heute gegen ihn aufgelehnt!" },
      { number: 17, text: "Haben wir denn noch nicht genug an der Sünde mit dem Baal-Peor, die bis heute auf uns liegt? Ihr wisst, dass die ganze Gemeinde Jahwes schwer dafür zu büßen hatte.*", footnotes: ["zu büßen hatte. Siehe 4. Mose 25,1-18."] },
      { number: 18, text: "Und was tut ihr? Ihr wendet euch heute von Jahwe ab! Doch wenn ihr das tut, wird schon morgen sein Zorn die ganze Gemeinde Israels treffen." },
      { number: 19, text: "Wenn ihr aber denkt, dass euer Land unrein ist, dann kommt herüber in das Land, das Jahwe gehört und wo er seine Wohnung aufgeschlagen hat, und siedelt euch unter uns an. Aber gegen Jahwe dürft ihr euch nicht auflehnen und auch nicht gegen uns, indem ihr euch einen anderen Altar als den Altar Jahwes, unseres Gottes, baut." },
      { number: 20, text: "Denkt an Achan Ben-Serach, der sich an dem Gebannten vergriff! Seine Schuld hat nicht nur ihm, sondern auch vielen anderen von uns das Leben gekostet.\"*", footnotes: ["das Leben gekostet. Siehe Josua 7."] },
      { number: 21, text: "Da erwiderten die Männer von Ruben, Gad und Ost-Manasse den Oberhäuptern der Heereseinheiten Israels:" },
      { number: 22, text: "\"Jahwe, der Gott und Herr aller Götter, ja, Gott, der Herr aller Götter, weiß es, und Israel soll es auch wissen: Wenn das Untreue und Auflehnung gegen Jahwe gewesen war, dann soll er uns heute nicht retten." },
      { number: 23, text: "Ob wir uns einen Altar gebaut haben, um uns von Jahwe abzuwenden, und ob wir Brand- und Speisopfer darauf opfern oder Freudenopferfeste feiern wollten, möge Jahwe selbst entscheiden!" },
      { number: 24, text: "Nein, wir haben das aus Sorge um unsere Nachkommen getan. Wir fürchteten, dass eure Kinder eines Tages zu unseren sagen könnten: 'Was habt ihr denn mit Jahwe, dem Gott Israels, zu tun?" },
      { number: 25, text: "Jahwe hat doch eine Grenze zwischen euch und uns gesetzt, ihr Söhne von Ruben und Gad, nämlich den Jordan. Ihr habt keinen Anspruch darauf, Jahwe zu dienen!' So könnten eure Kinder unsere davon abbringen, Jahwe zu fürchten." },
      { number: 26, text: "Darum haben wir diesen Altar gebaut. Er ist nicht für Brand- oder Schlachtopfer bestimmt," },
      { number: 27, text: "sondern soll auch für unsere Nachkommen ein Zeuge zwischen uns und euch sein. Er soll uns daran erinnern, Jahwe mit Brand- und Schlachtopfern und Opfermahlen zu dienen. Dann können eure Kinder nicht zu unseren sagen, sie würden nicht zur Gemeinde Jahwes gehören." },
      { number: 28, text: "Und sollten sie es doch eines Tages tun, dann könnten wir sagen: 'Seht euch diese Nachbildung von Jahwes Altar an! Unsere Väter haben sie gemacht. Sie wollten aber keine Opfer darauf bringen, sondern ihn als Denkmal zwischen uns stellen.'" },
      { number: 29, text: "Wir haben nicht im Entferntesten daran gedacht, uns gegen Jahwe aufzulehnen und ihm den Rücken zu kehren, indem wir neben dem Altar vor der Wohnung Jahwes noch einen Altar für Brand-, Speis- oder Schlachtopfer bauten.\"" },
      { number: 30, text: "Als der Priester Pinhas und die Fürsten der Gemeinschaft, die als Häupter der Heereseinheiten Israels bei ihm waren, hörten, was die Männer von Ruben, Gad und Ost-Manasse zu ihrer Verteidigung vorbrachten, waren sie beruhigt." },
      { number: 31, text: "Pinhas, der Sohn des Priesters Eleasar, sagte zu ihnen: \"Jetzt wissen wir, dass Jahwe weiter in unserer Mitte ist, denn ihr habt ihm nicht die Treue gebrochen. Damit habt ihr die Israeliten vor der Strafe Jahwes bewahrt.\"" },
      { number: 32, text: "Dann kehrten Pinhas und die Abgesandten Israels ins Land Kanaan zurück und brachten den Israeliten die Antwort von den Männern der Stämme Ruben und Gad aus Gilead." },
      { number: 33, text: "Diese freuten sich über die Antwort und dankten Gott. Jetzt dachten sie nicht mehr daran, gegen sie in den Krieg zu ziehen und ihr Land zu verwüsten." },
      { number: 34, text: "Die Rubeniten und die Gaditen gaben dem Altar einen Namen und erklärten: \"Er steht als Zeichen zwischen uns und bezeugt, dass Jahwe Gott ist.\"" },
    ] },
    { number: 23, verses: [
      { number: 1, text: "Seit Jahwe Israel Ruhe vor all seinen Feinden verschafft hatte, war eine lange Zeit vergangen. Josua war inzwischen sehr alt geworden.", heading: "Josuas Mahnung" },
      { number: 2, text: "Da rief er noch einmal ganz Israel zusammen, die Ältesten, die Oberhäupter, die Richter und die Aufseher*. Er sagte zu ihnen: \"Ich bin nun alt und habe nicht mehr lange zu leben.", footnotes: ["Aufseher. Aufsichtsbeamte mit bestimmten polizeilichen Vollmachten."] },
      { number: 3, text: "Ihr habt mit eigenen Augen gesehen, was Jahwe, euer Gott, mit allen Völkern hier gemacht hat, denn er war es, der für euch kämpfte." },
      { number: 4, text: "Und ich habe euch auch das noch nicht eroberte Land dieser Völker zwischen dem Jordan und dem Großen Meer im Westen zugeteilt." },
      { number: 5, text: "Jahwe, euer Gott, wird auch diese Völker vor euch vertreiben, und ihr werdet deren Land in Besitz nehmen, wie er es versprochen hat." },
      { number: 6, text: "Lasst euch deshalb nicht davon abbringen, alles zu befolgen, was im Gesetzbuch des Mose geschrieben steht. Haltet euch ganz fest daran und weicht weder rechts noch links davon ab," },
      { number: 7, text: "damit ihr euch nicht mit den Völkern vermischt, die noch übrig geblieben sind. Nehmt die Namen ihrer Götter nicht in den Mund und schwört nicht bei ihnen! Verehrt sie nicht und betet sie nicht an." },
      { number: 8, text: "Nur Jahwe, eurem Gott, sollt ihr anhängen und ihm die Treue halten, wie ihr es bis jetzt getan habt." },
      { number: 9, text: "Jahwe hat große und starke Völker vor euch vertrieben, und bis heute konnte euch niemand standhalten." },
      { number: 10, text: "Ein Einziger von euch jagt tausend, denn Jahwe, euer Gott, kämpft für euch, wie er es versprochen hat." },
      { number: 11, text: "Euer Leben hängt davon ab, dass ihr Jahwe, euren Gott, liebt!" },
      { number: 12, text: "Denn wenn ihr euch von ihm abwendet und euch mit den Völkern einlasst, die bei euch noch übrig geblieben sind, wenn ihr euch mit ihnen verschwägert und vermischt," },
      { number: 13, text: "dann sollt ihr mit Sicherheit wissen: Jahwe, euer Gott, wird sie nicht weiter vor euch vertreiben. Dann werden sie für euch zum Fangnetz und zur Falle, zu Stachelpeitschen in euren Seiten und zu Dornen im Gesicht, bis ihr zugrunde geht und aus diesem guten Land fort müsst, das euer Gott euch gegeben hat." },
      { number: 14, text: "Ich werde bald den Weg alles Irdischen gehen. Doch ihr habt ja mit Herz und Seele erkannt, dass all die guten Worte, die Jahwe, euer Gott, euch gesagt hat, eingetroffen sind; kein einziges davon ist ausgeblieben." },
      { number: 15, text: "Aber genauso, wie sich jedes gute Wort Jahwes bei euch erfüllt hat, wird sich auch all das Böse erfüllen, das er euch angedroht hat – bis er euch wieder aus diesem schönen Land entfernt hat, das er euch gab." },
      { number: 16, text: "Wenn ihr den Bund brecht, den Jahwe, euer Gott, mit euch geschlossen hat, wenn ihr also andere Götter verehrt und euch vor ihnen niederwerft, dann wird euch Jahwes brennender Zorn treffen, und ihr werdet schnell aus dem guten Land verschwunden sein, das er euch gab.\"" },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Josua rief alle Stämme Israels nach Sichem zusammen: alle Ältesten, die Oberhäupter, Richter und Aufseher. Gemeinsam traten sie vor Gott,", heading: "Die Volksversammlung in Sichem" },
      { number: 2, text: "und Josua sagte zum Volk: \"So spricht Jahwe, der Gott Israels: 'Vor langer Zeit wohnten eure Vorfahren auf der anderen Seite des Stromes* und dienten fremden Göttern. Dazu gehörte auch Terach, der Vater von Abraham und Nahor.", footnotes: ["Strom. Das ist der Euphrat"] },
      { number: 3, text: "Aber dann holte ich euren Stammvater Abraham aus dem Land jenseits des Stromes und ließ ihn im ganzen Land Kanaan umherziehen. Ich schenkte ihm viele Nachkommen: Ich gab ihm Isaak," },
      { number: 4, text: "Isaak schenkte ich Jakob und Esau. Esau erhielt das Gebirge Seïr, doch Jakob und seine Söhne wanderten nach Ägypten aus." },
      { number: 5, text: "Dann schickte ich Mose und Aaron zu euren Vorfahren. Ich ließ schweres Unheil über Ägypten kommen und führte eure Vorfahren wieder aus dem Land." },
      { number: 6, text: "Ich brachte sie von Ägypten bis ans Schilfmeer. Doch die Ägypter verfolgten sie mit Streitwagen und Reitern." },
      { number: 7, text: "Da schrien sie zu Jahwe, und er ließ zwischen ihnen und den Ägyptern eine Finsternis hereinbrechen; und dann ließ er das Meer über die Ägypter kommen, sodass sie untergingen. Ihr habt selbst gesehen, was ich mit Ägypten gemacht habe. Anschließend lebtet ihr lange Zeit in der Wüste." },
      { number: 8, text: "Ich brachte euch dann in das Land der Amoriter östlich des Jordan. Sie kämpften gegen euch, doch ich gab sie in eure Hand. Ich vernichtete sie, und ihr konntet ihr Land in Besitz nehmen." },
      { number: 9, text: "Auch der Moabiterkönig Balak Ben-Zippor kämpfte gegen Israel. Er ließ Bileam Ben-Beor rufen, um euch zu verfluchen." },
      { number: 10, text: "Aber ich wollte nicht auf Bileam hören, und er musste euch nachdrücklich segnen. So rettete ich euch vor seinen Anschlägen." },
      { number: 11, text: "Dann habt ihr den Jordan überschritten und seid bis nach Jericho gekommen. Doch die Bürger von Jericho und die Amoriter, die Perisiter, die Kanaaniter, die Hetiter, die Girgaschiter, die Hiwiter und die Jebusiter kämpften gegen euch. Aber ich gab sie alle in eure Hand." },
      { number: 12, text: "Ich sandte Angst und Schrecken vor euch her. Die vertrieben sie vor euch, genau wie vorher die beiden Amoriterkönige. Es war nicht dein Schwert und dein Bogen!" },
      { number: 13, text: "Ich gab euch ein Land, das ihr nicht nutzbar machen musstet, und Städte, die ihr nicht gebaut hattet. Jetzt wohnt ihr darin und esst von Weinbergen und Ölbäumen, die ihr nicht gepflanzt habt.'\"" },
      { number: 14, text: "\"Darum fürchtet Jahwe\", fuhr Josua fort, \"und dient ihm aufrichtig und treu! Trennt euch von den Göttern, denen eure Vorfahren im Land jenseits des Stromes und in Ägypten gedient haben! Dient allein Jahwe!" },
      { number: 15, text: "Wenn euch das aber nicht gefällt, dann entscheidet euch heute, wem ihr dienen wollt: den Göttern, die eure Vorfahren jenseits des Stromes verehrt haben, oder den Göttern der Amoriter, in deren Land ihr lebt. Doch ich und meine ganze Familie – wir werden Jahwe dienen!\"" },
      { number: 16, text: "Da erwiderte das Volk: \"Nein, wir wollen Jahwe nicht verlassen, um anderen Göttern zu dienen!" },
      { number: 17, text: "Es war doch Jahwe, der unsere Vorfahren aus der Sklaverei in Ägypten befreit hat, es war unser Gott, der vor unseren Augen so große Wunder getan und uns auf dem ganzen Weg quer durch das Gebiet fremder Völker beschützt hat." },
      { number: 18, text: "Jahwe war es doch, der alle Völker und auch die Amoriter, die dieses Land bewohnten, vor uns vertrieben hat. Auch wir wollen Jahwe dienen, denn er ist unser Gott!\"" },
      { number: 19, text: "Aber Josua sagte zum Volk: \"Ihr seid nicht in der Lage, Jahwe zu dienen, denn er ist ein heiliger Gott, der eifersüchtig darüber wacht, dass ihr allein ihm gehört. Er wird euch nicht vergeben, wenn ihr ihm untreu werdet." },
      { number: 20, text: "Wenn ihr Jahwe verlasst und anfangt, fremden Göttern zu dienen, wird er sich gegen euch wenden. Er wird euch Böses antun und euch vernichten, obwohl er euch vorher Gutes erwiesen hat.\"" },
      { number: 21, text: "Aber das Volk erwiderte: \"Wir wollen trotzdem Jahwe dienen!\"" },
      { number: 22, text: "Da sagte Josua: \"Ihr seid Zeugen gegen euch selbst, dass ihr euch für Jahwe entschieden habt und ihm dienen wollt!\" – \"Ja, wir sind Zeugen!\", riefen sie." },
      { number: 23, text: "\"Dann schafft auch die fremden Götter weg, die ihr noch bei euch habt\", sagte Josua, \"und wendet euch mit ganzem Herzen Jahwe, dem Gott Israels, zu!\"" },
      { number: 24, text: "Das Volk erwiderte: \"Jahwe, unserem Gott, wollen wir dienen! Auf seine Stimme wollen wir hören!\"" },
      { number: 25, text: "An diesem Tag in Sichem verpflichtete Josua das Volk auf den Bund mit Gott und legte ihnen die Gebote und Rechtsordnungen vor." },
      { number: 26, text: "Dann schrieb er alles in das Gesetzbuch Gottes. Schließlich nahm er einen großen Stein und richtete ihn unter der Terebinthe auf, die beim Heiligtum Jahwes steht." },
      { number: 27, text: "\"Seht diesen Stein!\", rief er dem Volk zu, \"er ist Zeuge, denn er hat alles gehört, was Jahwe zu uns gesagt hat. Er soll euch erinnern und mahnen, euren Gott nicht zu verleugnen!\"" },
      { number: 28, text: "Dann entließ Josua das Volk, und jeder kehrte in seinen Erbbesitz zurück." },
      { number: 29, text: "Nach diesen Ereignissen starb Josua Ben-Nun, der Diener Jahwes, im Alter von 110 Jahren.", heading: "Josuas Tod" },
      { number: 30, text: "Man begrub ihn in Timnat-Serach, das im Gebirge Efraïm nördlich vom Berg Gaasch liegt, auf dem Grundstück, das zu seinem Erbbesitz gehörte." },
      { number: 31, text: "Solange Josua gelebt hatte und auch solange die Ältesten noch lebten, die alles miterlebt hatten, was Jahwe für Israel tat, blieb das Volk seinem Gott treu." },
      { number: 32, text: "Sie begruben auch die Gebeine Josefs, die sie aus Ägypten mitgebracht* hatten, und zwar in Sichem auf dem Grundstück, das Jakob von den Söhnen Hamors, des Vaters von Sichem, für 100 Kesita* gekauft hatte und das jetzt zum Erbbesitz der Nachkommen Josefs zählte.", footnotes: ["Gebeine ... mitgebracht. Die waren 400 Jahre vorher dort einbalsamiert worden, siehe 1. Mose 50,25-26.", "Kesita. Geldeinheit/Geldgewicht ist bis heute unbekannt."] },
      { number: 33, text: "Dann starb auch Eleasar, der Sohn Aarons. Er wurde in Gibea begraben, einer Stadt im Gebirge Efraïm, die seinem Sohn Pinhas als Wohnsitz zugeteilt worden war." },
    ] },
  ],
};